himal-apricot.source:
// Apricot orchard tree: a short gnarled trunk twisting into 3-4 limbs under a rounded, lumpy crown of leaf clusters,
// fresh green with a few apricot-orange fruit dots. Root at the origin. About 600 triangles.
const H=params.height, R=function(){return api.rng();};
const bark={finish:'bark',color:params.trunkColor,roughness:0.95};
const leaf={preset:'leaf',color:'#ffffff',vertexColors:true,roughness:0.9};
const th=H*0.32, lean=(R()-0.5)*0.5;
// trunk: a bent tube that thins and twists
const tp=[];for(let k=0;k<=4;k++){const t=k/4;tp.push([lean*t*t*1.2+0.08*Math.sin(t*5+R()),th*t,0.1*Math.sin(t*4+R()*3)]);}
let wood=api.tube(tp,0.16,6);
const top=tp[tp.length-1];
const nl=3+Math.floor(R()*2);const tips=[];
for(let i=0;i<nl;i++){const a=i*6.283/nl+R()*0.8, out=H*(0.18+0.08*R()), up=H*(0.2+0.1*R());
 const mid=[top[0]+Math.cos(a)*out*0.5,top[1]+up*0.45,top[2]+Math.sin(a)*out*0.5];
 const end=[top[0]+Math.cos(a)*out,top[1]+up,top[2]+Math.sin(a)*out];
 wood=wood.merge(api.tube([top,mid,end],0.08,5));tips.push(end);}
api.add(wood.displace(function(x,y,z){return 0.02*api.noise3(x*6,y*6,z*6);}),bark);
// crown: a few overlapping lumpy blobs round the limb tips, shaded darker inside and lower down
const cy=th+H*0.3, cr=H*0.33;let crown=null;
const blobs=[[0,cy+cr*0.15,0,cr*0.85]];for(const t of tips)blobs.push([t[0]*0.8,t[1]+cr*0.05,t[2]*0.8,cr*(0.55+0.15*R())]);
const sd=R()*30;
for(const b of blobs){const m=api.sphere(b[3],1).scale(1,0.78,1).displace(function(x,y,z){return b[3]*(0.16*api.noise3(x*1.6+sd,y*1.6,z*1.6)+0.07*api.noise3(x*5,y*5+sd,z*5));}).translate(b[0],b[1],b[2]);crown=crown?crown.merge(m):m;}
crown.vertexColor(function(x,y,z){const n=api.noise3(x*2.2+sd,y*2.2,z*2.2),f=api.noise3(x*7,y*7,z*7+sd);
 if(f>0.55)return '#e8902a';
 const lit=Math.min(1,Math.max(0,(y-th)/(H-th)));return api.mix(api.mix('#3f5e22',params.color,0.35+0.55*lit),'#9cbf55',Math.max(0,n)*0.4);});
api.add(crown,leaf);
api.collider({kind:'cylinder',halfHeight:th/2,radius:0.22,offset:[0,th/2,0]});
return api.build();

himal-arch-bridge.source:
const L=params.length,W=params.width,n=Math.max(1,Math.round(params.arches)),H=params.hump,D=params.depth,col=params.color;
const top=function(x){return H*(1-Math.pow(2*x/L,2));};
const slope=function(x){return Math.atan(-8*H*x/(L*L))*180/Math.PI;};
const abut=Math.max(2.5,L*0.08),pw=Math.max(1.1,W*0.32);
const s=(L-2*abut-(n-1)*pw)/n,r=s/2;
const layers=[{kind:'tone',amount:0.5},{kind:'grime',amount:0.5},{kind:'streaks',amount:0.4},{kind:'moss',amount:0.35,mask:{noise:0.5}},{kind:'edgeWear',amount:0.45}];
const stone={preset:'stone',finish:'stone',color:col,roughness:0.93,surface:{layers:layers}};
const dress={preset:'stone',finish:'stone',color:api.mix(col,'#5e574e',0.25),roughness:0.9,surface:{layers:layers}};
const pave={preset:'stone',finish:'stone',color:api.mix(col,'#6d665c',0.35),roughness:0.95,surface:{layers:[{kind:'tone',amount:0.6},{kind:'grime',amount:0.6},{kind:'lichen',amount:0.3}]}};
const cx=[],ys=[];
for(let k=0;k<n;k++){const c=-L/2+abut+r+k*(s+pw);cx.push(c);ys.push(top(c)-0.95-r);}
const pts=[[-L/2,-D]];const N=48;
for(let i=0;i<=N;i++){const x=-L/2+L*i/N;pts.push([x,top(x)-0.15]);}
pts.push([L/2,-D]);
for(let k=n-1;k>=0;k--){const c=cx[k];pts.push([c+r,-D]);pts.push([c+r,ys[k]]);for(let j=1;j<16;j++){const a=j/16*Math.PI;pts.push([c+r*Math.cos(a),ys[k]+r*Math.sin(a)]);}pts.push([c-r,ys[k]]);pts.push([c-r,-D]);}
api.add(api.extrude(pts,W-0.1),stone);
let vm=null;const m=15;
for(let k=0;k<n;k++){for(const f of [-1,1]){for(let j=0;j<m;j++){const a=(j+0.5)/m*Math.PI;const tang=Math.PI*(r+0.3)/m*0.9;const v=api.box(0.62,tang,0.16).rotate(0,0,a*180/Math.PI).translate(cx[k]+(r+0.3)*Math.cos(a),ys[k]+(r+0.3)*Math.sin(a),f*((W-0.1)/2+0.02));vm=vm?vm.merge(v):v;}}}
for(let k=0;k<n-1;k++){const px=cx[k]+r+pw/2;const h=(Math.min(ys[k],ys[k+1])+0.4)+D;for(const f of [-1,1]){const cw=api.extrude([[-pw/2,0],[pw/2,0],[0,1.1]],h).rotate(f*90,0,0).translate(px,-D+h/2,f*((W-0.1)/2-0.02));vm=vm.merge(cw);const cap=api.box(pw*0.8,0.22,0.8).translate(px,-D+h+0.11,f*((W-0.1)/2+0.3));vm=vm.merge(cap);}}
api.add(vm,dress);
let pm=null;
for(const f of [-1,1]){const pp=[];for(let i=0;i<=N;i++){const x=-L/2+L*i/N;pp.push([x,top(x)+0.85]);}for(let i=N;i>=0;i--){const x=-L/2+L*i/N;pp.push([x,top(x)-0.16]);}const par=api.extrude(pp,0.38).translate(0,0,f*(W/2-0.24));pm=pm?pm.merge(par):par;
for(let x=-L/2+0.31;x<L/2-0.2;x+=0.62){const c=api.box(0.6,0.14,0.5).rotate(0,0,slope(x)).translate(x,top(x)+0.92,f*(W/2-0.24));pm.merge(c);}
const path=[];for(let i=0;i<=N;i++){const x=-L/2+L*i/N;path.push([x,top(x)-0.28,f*(W/2-0.02)]);}pm.merge(api.tube(path,0.08,6));}
api.add(pm,dress);
const inner=W-0.86;const c3=3;let sm=null;let row=0;
for(let x=-L/2+0.25;x<L/2-0.2;x+=0.46){const off=(row%2)*0.5;row++;for(let q=0;q<c3;q++){let z0=-inner/2+(q+off)*inner/c3;let w=inner/c3-0.04;let zc=z0+w/2;if(zc+w/2>inner/2){w=inner/2-z0-0.04;zc=z0+w/2;}if(w<0.15)continue;const st=api.roundedBox(0.43,0.12,w,0.03,1).rotate(0,0,slope(x)+(api.rng()-0.5)*1.5).translate(x,top(x)-0.1+api.rng()*0.02,zc);sm=sm?sm.merge(st):st;}
if(off>0){const w=inner/(2*c3)-0.04;const st=api.roundedBox(0.43,0.12,w,0.03,1).rotate(0,0,slope(x)).translate(x,top(x)-0.1,-inner/2+w/2+0.02);sm.merge(st);}}
api.add(sm,pave);
api.autoColliders('trimesh');
return api.build();

himal-boulder.source:
// a weathered boulder: a smooth lumpy mass (two octaves of low noise on a subdivided sphere), a flatter base bedded in
// the ground, cracks and lichen from the surface layers; detail 2 is about 320 triangles
const r=params.size/2, rng=api.rng;
const m=api.icosphereRock(r,0.35+0.3*rng(),params.detail|0);
const s1=rng()*50,s2=rng()*50,fl=0.55+0.25*rng();
m.displace(function(x,y,z){return r*(0.1*api.noise3(x/r*1.7+s1,y/r*1.7,z/r*1.7-s2)+0.04*api.noise3(x/r*4.1-s2,y/r*4.1+s1,z/r*4.1));});
m.warp(function(x,y,z){const yy=y<0?y*0.45:y;return [x*(1+0.15*rng()*0),yy*fl,z*(0.8+0.25*fl)];});
m.vertexColor(function(x,y,z){const n=0.5+0.5*api.noise3(x*1.3/r+s1,y*1.3/r,z*1.3/r);const up=y/(r*fl);
 let c=api.mix(api.mix(params.color,'#5e5850',0.35),api.mix(params.color,'#b3a998',0.3),n);
 c=api.mix(c,'#8b8a4e',params.lichen*0.6*Math.max(0,up)*n);return api.mix(c,'#3f3a33',0.4*Math.max(0,-up));});
api.add(m,{finish:'rock',color:'#ffffff',vertexColors:true,roughness:0.9,surface:{layers:[{kind:'lichen',amount:params.lichen},{kind:'grime',amount:0.3}]}});
api.collider({kind:'sphere',radius:r*0.8,offset:[0,r*0.5,0]});
return api.build();

himal-channel.source:
const L=params.length,bow=params.bow,drop=params.drop,w=params.width;
const N=Math.max(10,Math.round(L/1.5));
const mid=[],bed=[],kl=[],kr=[];
const stoneMat={preset:'stone',finish:'stone',color:'#8d877c',roughness:0.9,surface:{layers:[{kind:'moss',amount:0.45,mask:{noise:0.5}},{kind:'grime'},{kind:'edgeWear'}]}};
let rocks=null;
for(let i=0;i<=N;i++){const t=i/N;const x=-L/2+L*t;const u=2*t-1;const z=bow*(1-u*u);const y=drop*(1-t)+0.25;const d=-4*bow*u/L;const len=Math.sqrt(1+d*d);const nx=-d/len,nz=1/len;
mid.push([x,y+0.02,z]);bed.push([x,y-0.06,z]);
const o=w/2+0.1;kl.push([x+nx*o,y,z+nz*o]);kr.push([x-nx*o,y,z-nz*o]);
if(i%1===0){for(let s=-1;s<=1;s+=2){const r=0.09+api.rng()*0.1;const m=api.icosphereRock(r,0.5).scale(1.3,0.7,1).rotate(0,api.rng()*360,0).translate(x+s*nx*(o+0.18)+(api.rng()-0.5)*0.4,y-0.08,z+s*nz*(o+0.18)+(api.rng()-0.5)*0.4);rocks=rocks?rocks.merge(m):m;}}}
const soil=api.ribbon(bed,w+0.3);api.add(soil,{preset:'dirt',finish:'soil',color:'#6b5642',roughness:1});
const water=api.ribbon(mid,w*0.82);api.add(water,{preset:'water',waterKind:'stream',waterFlow:[0.6,0],color:'#6fb2ad',opacity:0.85});
const kerbL=api.tube(kl,0.16,8).displace((x,y,z)=>0.035*api.noise3(x*3,y*3,z*3));
const kerbR=api.tube(kr,0.16,8).displace((x,y,z)=>0.035*api.noise3(x*3+7,y*3,z*3));
api.add(kerbL.merge(kerbR),stoneMat);
if(rocks)api.add(rocks,stoneMat);
const skirt=api.box(L,0.5,w+0.8).translate(0,drop*0.5-0.1,0);api.add(skirt,{preset:'dirt',finish:'soil',color:'#5e4b3a',roughness:1});
return api.build();

himal-chorten.source:
function RB1(a,b,c,r){return api.roundedBox(a,b,c,r,1);}
const k = params.height / 6;
const white = {finish:'plaster', color: params.color, roughness:0.85, surface:{layers:[{kind:'tone',amount:0.3},{kind:'grime',amount:0.45},{kind:'streaks',amount:0.35},{kind:'lichen',amount:0.15}]}};
const stone = {finish:'stone', color:'#8f877b', roughness:0.9, surface:{layers:[{kind:'grime',amount:0.4},{kind:'moss',amount:0.35,mask:{up:0.5}},{kind:'edgeWear'}]}};
const red = {finish:'plaster', color:'#8a2c22', roughness:0.8, surface:{layers:[{kind:'grime',amount:0.3}]}};
const gold = {finish:'brass', color:'#d4a640', metalness:0.85, roughness:0.35, surface:{layers:[{kind:'grime',amount:0.2}]}};
let y = 0;
api.add(RB1(3.2*k, 0.5*k, 3.2*k, 0.07*k, 2).translate(0, 0.25*k, 0), stone);
y = 0.5*k;
const tiers = [2.8, 2.45, 2.1];
for (let i = 0; i < tiers.length; i++) {
  const w = tiers[i]*k, h = 0.42*k;
  api.add(RB1(w, h, w, 0.05*k, 2).translate(0, y + h/2, 0), white);
  y += h;
}
api.add(RB1(2.15*k, 0.12*k, 2.15*k, 0.03*k, 1).translate(0, y + 0.06*k, 0), red);
y += 0.12*k;
const dome = [[0,0],[0.9,0],[0.95,0.08],[0.95,0.22],[1.0,0.3],[1.0,0.62],[0.92,0.95],[0.72,1.22],[0.42,1.4],[0,1.46]].map(function(p){return [p[0]*k, p[1]*k];});
api.add(api.lathe(dome, 28).translate(0, y, 0), white);
const domeBase = y;
y += 1.4*k;
api.add(RB1(0.72*k, 0.42*k, 0.72*k, 0.04*k, 2).translate(0, y + 0.21*k, 0), white);
api.add(RB1(0.8*k, 0.1*k, 0.8*k, 0.02*k, 1).translate(0, y + 0.42*k, 0), red);
y += 0.47*k;
const sp = [[0,0]];
for (let i = 0; i < 13; i++) {
  const r = (0.3 - i*0.016)*k, yy = i*0.11*k;
  sp.push([r, yy]); sp.push([r*0.82, yy + 0.07*k]);
}
sp.push([0.07*k, 13*0.11*k]); sp.push([0, 13*0.11*k]);
api.add(api.lathe(sp, 20).translate(0, y, 0), gold);
y += 13*0.11*k;
api.add(api.lathe([[0,0],[0.34*k,0],[0.34*k,0.03*k],[0.06*k,0.14*k],[0,0.15*k]], 20).translate(0, y, 0), gold);
y += 0.15*k;
api.add(api.sphere(0.08*k, 2).translate(0, y + 0.07*k, 0), gold);
api.add(api.lathe([[0,0],[0.03*k,0],[0.015*k,0.22*k],[0,0.24*k]], 10).translate(0, y + 0.13*k, 0), gold);
api.collider({kind:'box', halfExtents:[1.6*k, (domeBase)/2, 1.6*k], offset:[0, domeBase/2, 0]});
api.collider({kind:'cylinder', halfHeight:0.75*k, radius:0.95*k, offset:[0, domeBase + 0.75*k, 0]});
return api.build();

himal-cliff.source:
function ss(a,b,x){let t=(x-a)/(b-a); t=t<0?0:(t>1?1:t); return t*t*(3-2*t);}
function rx(z){return 25*Math.sin(z*0.011)+12*Math.sin(z*0.029+1);}
function fl(z){return 26*ss(-80,-300,z);}
const TS=1.5, FX=-100, FZ=-40, LIP=params.lip, R=params.relief;
function terr(x,z,d){return ss(46,56,d)*(1-ss(118,138,d))*ss(-80,-58,z)*(1-ss(128,150,z))*(1-(1-ss(62,80,Math.abs(z-FZ)))*ss(-45,-60,x));}
function sz(x){return FZ+2.5*Math.sin(x*0.09)+1.5*Math.sin(x*0.23);}
function H(x,z,P){
 const d=Math.abs(x-rx(z));
 const n=api.fbm2(x*0.011,z*0.011,4);
 const n2=api.fbm2(x*0.05+7,z*0.05-3,2);
 const f=fl(z);
 let s=Math.pow(ss(28,240,d),1.25)*R*(1+0.35*n)*(1-0.3*ss(0,60,x-rx(z)));
 const band=ss(90,140,z)*(1-ss(230,280,z));
 const g=22*ss(12,26+4*n2,d)*band;
 const ero=ss(40,200,d)*8*(n2*0.5+0.5)*(0.5+0.5*n);
 let h=f+s+g+ero+2.2*n2*ss(14,40,d);
 const c=1-ss(7,15+3*n2,d);
 h=h*(1-c)+(f-3)*c;
 // fine erosion: rills down the slopes and small knolls
 h+=ss(20,60,d)*(0.9*api.fbm2(x*0.09,z*0.03,2)+0.3*api.noise2(x*0.31,z*0.31));
 // terraced barley fields cut into both slopes, following the contours
 const T=terr(x,z,d);
 if(T>0.001){const o=0.9*api.noise2(x*0.025,z*0.025);const hn=h+o;const k=Math.floor(hn/TS);const fr=hn/TS-k;const ht=k*TS+TS*ss(0.8,0.97,fr)-o;h=h*(1-T)+(ht-(P?0:1.0))*T;}
 // hanging valley on the west wall: an escarpment with a notch whose floor (LIP) is the lip of the fall
 const az=Math.abs(z-FZ);const wb=1-ss(48,72,az);
 if(wb>0){const notch=1-ss(9,20,az+1.5*api.noise2(x*0.08,1.3));const E=LIP+13*(1-notch)+1.2*api.noise2(x*0.07,z*0.07)-1.0*notch*ss(FX-2,FX-30,x);
  const cl=ss(FX+3,FX-4,x+2*api.noise2(z*0.15,x*0.15))*wb;h=Math.max(h,h*(1-cl)+E*cl);
  const fm=ss(FX+11,FX+6,x)*(1-ss(FX+3.5,FX+1.5,x))*(1-ss(3,7,Math.abs(z-FZ)));h-=1.6*fm;}
 // the stream from the plunge pool to the river
 const xr=rx(FZ);
 if(x>FX+2&&x<xr){const dz=Math.abs(z-sz(x));h-=0.7*(1-ss(1.4,3.2,dz))*ss(FX+2,FX+6,x);}
 return h<-3?-3:h;
}// ---- rock skin over the escarpment of the hanging valley, conforming to the valley ground (same height code, same grid)
const CX=params.cx, CZ=params.cz, ZW=params.zw, X0=params.x0, X1=params.x1, Y0=params.y0, Y1=params.y1;
const TW=params.size, TD=params.length, TN=params.res;
// the valley mesh is a TN x TN grid over TW x TD; sample H on its nodes and interpolate like the rendered ground
const gi0=Math.floor((X0+TW/2)/TW*(TN-1))-1, gi1=Math.ceil((X1+TW/2)/TW*(TN-1))+1;
const gj0=Math.floor((CZ-ZW/2-2+TD/2)/TD*(TN-1))-1, gj1=Math.ceil((CZ+ZW/2+2+TD/2)/TD*(TN-1))+1;
const GW=gi1-gi0+1, GG=new Array(GW*(gj1-gj0+1));
for(let j=gj0;j<=gj1;j++)for(let i=gi0;i<=gi1;i++)GG[(j-gj0)*GW+(i-gi0)]=H(-TW/2+TW*i/(TN-1),-TD/2+TD*j/(TN-1),0);
function L(x,z){let fi=(x+TW/2)/TW*(TN-1)-gi0,fj=(z+TD/2)/TD*(TN-1)-gj0;fi=Math.max(0,Math.min(GW-1.001,fi));fj=Math.max(0,Math.min(gj1-gj0-0.001,fj));
 const i=Math.floor(fi),j=Math.floor(fj),u=fi-i,v=fj-j;const a=GG[j*GW+i],b=GG[j*GW+i+1],c=GG[(j+1)*GW+i],e=GG[(j+1)*GW+i+1];return (a*(1-u)+b*u)*(1-v)+(c*(1-u)+e*u)*v;}
function hash(a,b){const s=Math.sin(a*127.1+b*311.7)*43758.5453;return s-Math.floor(s);}
// where the ground passes height y along x (west high, east low): bisection on the first crossing from the west
function cross(y,z){let xa=X0,ha=L(xa,z);if(ha<y)return {x:X0,top:true};
 for(let x=X0+0.5;x<=X1;x+=0.5){const h=L(x,z);if(h<y){let lo=x-0.5,hi=x;for(let k=0;k<12;k++){const m=(lo+hi)/2;if(L(m,z)>y)lo=m;else hi=m;}return {x:(lo+hi)/2,top:false};}}
 return {x:X1,top:false,low:true};}
// strata: ledges that jut at the top of each bed and undercut below it, blocky joints along each bed
function strata(y,z){const yy=y+1.4*api.noise2(z*0.04,3.3);const t=2.4+0.9*api.noise2(z*0.02,9.1);const k=Math.floor(yy/t),fr=yy/t-k;
 const blk=Math.floor((z+40*hash(k,1))/(2.4+3.6*hash(k,2)));const jz=(z+40*hash(k,1))/(2.4+3.6*hash(k,2))-blk;
 const jut=0.6+2.4*hash(k,blk);
 const joint=1-0.65*(1-ss(0,0.08,jz))-0.65*ss(0.92,1,jz);
 return jut*joint*(0.15+0.85*Math.pow(fr,0.4));}
// buttresses: vertical ribs and gullies (joint sets weathered open), and broad bulges of the wall
function ribs(y,z){const u=z/6.5+0.6*api.noise2(y*0.05,z*0.02);const f=u-Math.floor(u);const r=1-Math.abs(2*f-1);return 2.6*r*r*(0.6+0.4*api.noise2(Math.floor(u)*3.7,1.1));}
// ---- the cliff behind the fall: a concave rock wall (an amphitheatre) standing in front of the escarpment, from below
// the ground at the foot up to the lip of the hanging valley, its top rounding back into the plateau and its ends turning
// into the slope; a recessed chute down the fall line
const FXf=params.faceX, HW=params.halfWidth, DZc=0.5;
function faceX(z){const u=(z-FZ)/HW;const a=Math.abs(u);return FXf-params.concave*(1-u*u)-12*ss(0.62,1,a)+0.8*api.noise2(z*0.07,1.7);}
function topY(z){const xf=faceX(z);let t=-1e9;for(let x=xf-6;x<=xf-2;x+=1)t=Math.max(t,L(x,z));return t+0.35;}
function wetAt(z){return Math.exp(-Math.pow((z-FZ)/(params.width*0.75),2));}
function off(y,z,t){const end=1-ss(0.6,0.98,Math.abs(z-FZ)/HW);const wet=wetAt(z);
 let o=(strata(y,z)+ribs(y,z)+1.6*api.fbm2(z*0.06+3,y*0.06,3)+0.25*api.noise2(z*1.3,y*1.3))*(0.3+0.7*end);
 o+=1.4*ss(0.8,0.97,t)*(1-ss(0.985,1,t))*end;
 o=o*(1-0.75*wet)-2.2*wet*(1-ss(0.9,1,t));
 return o-0.9*(1-end)-1.2;}
const NC=Math.round(2*HW/DZc)+1, NF=72, NK=8, NR=NF+NK;
const PX=new Array(NC*NR),PY=new Array(NC*NR),PZ=new Array(NC*NR),OO=new Array(NC*NR);
const YB=[],YT=[];
for(let c=0;c<NC;c++){const z=FZ-HW+c*DZc;const xf=faceX(z);const yt=topY(z);const yb=L(xf+1.5,z)-2.6;YB.push(yb);YT.push(yt);
 for(let r=0;r<NR;r++){const q=c*NR+r;let x,y,o=0;
  if(r<NF){const t=r/(NF-1);y=yb+(yt-yb)*Math.pow(t,0.92);o=off(y,z,t);x=xf+o;}
  else{const k=(r-NF+1)/NK;x=xf+0.6-k*9.5;y=(1-k)*(yt+0.3*Math.sin(k*3.1))+k*(L(x,z)-1.2)+0.3*api.noise2(z*0.3,k*3);o=0.5;}
  const e=ss(0.62,0.95,Math.abs(z-FZ)/HW);if(e>0)y=y*(1-e)+Math.min(y,L(x,z)-0.6)*e;
  PX[q]=x;PY[q]=y;PZ[q]=z;OO[q]=o;}}
const m=api.heightfield(NC,NR,2*HW,NR-1,function(){return 0;});
m.warp(function(x,y,z){const c=Math.max(0,Math.min(NC-1,Math.round((x+HW)/DZc))),r=Math.max(0,Math.min(NR-1,Math.round(z+NR/2-0.5)));const q=c*NR+r;return [PX[q]-CX,PY[q],PZ[q]-CZ];});
m.vertexColor(function(x,y,z){const X=x+CX,Z=z+CZ;const c=Math.max(0,Math.min(NC-1,Math.round((Z-(FZ-HW))/DZc)));
 let best=0,bd=1e9;for(let r=0;r<NR;r++){const q=c*NR+r;const dd=Math.abs(PY[q]-y)+Math.abs(PX[q]-X);if(dd<bd){bd=dd;best=q;}}
 const o=OO[best];const n=api.noise2(Z*0.25,y*0.25)*0.5+0.5,n2=api.noise2(Z*1.1,y*0.9)*0.5+0.5;
 let col=api.mix('#5d564e','#a69a88',Math.max(0,Math.min(1,0.25+0.18*o+0.35*n)));col=api.mix(col,'#94765a',0.28*n2);
 const w=wetAt(Z);col=api.mix(col,'#2c2b28',0.7*w*(0.6+0.4*n2));
 const g=L(X,Z);col=api.mix(col,'#55623a',0.55*(1-ss(g+0.5,g+4,y))*n);
 if(y>topY(Z)-0.8)col=api.mix(col,'#7a7350',0.45*n2);return col;});
api.add(m,{finish:'rock',color:'#ffffff',vertexColors:true,roughness:0.92,surface:{layers:[{kind:'strata',amount:0.4,scale:1.35},{kind:'lichen',amount:0.35},{kind:'moss',amount:0.3,mask:{up:0.7,noise:0.5}},{kind:'grime',amount:0.35}]}});
// fallen blocks at the foot of the wall
{let fb=null;for(let k=0;k<14;k++){const z=FZ+(api.rng()*2-1)*HW*0.6;if(Math.abs(z-FZ)<params.width*0.6)continue;const x=faceX(z)+1.5+api.rng()*3;const r=0.6+api.rng()*1.1;
 const b=api.icosphereRock(r,0.6).scale(1.2,0.75,1).rotate(0,api.rng()*180,0).translate(x-CX,L(x,z)+r*0.2,z-CZ);fb=fb?fb.merge(b):b;}
 if(fb)api.add(fb,{finish:'rock',color:'#8d8478',roughness:0.92,surface:{layers:[{kind:'lichen',amount:0.4},{kind:'moss',amount:0.3,mask:{up:0.6,noise:0.5}}]}});}
// the plunge pool: a ring of boulders bedded in the ground round the foot of the fall, a still pool inside
const PXc=params.poolX, PZc=FZ, PR=params.poolR;
let ground=1e9;for(let a=0;a<6.28;a+=0.4)ground=Math.min(ground,L(PXc+Math.cos(a)*PR*0.6,PZc+Math.sin(a)*PR*0.6));
let rocks=null;
for(let k=0;k<22;k++){const a=k/22*6.283+0.2*api.rng();if(Math.cos(a)<-0.55)continue;const rr=PR*(1.0+0.25*api.rng());const x=PXc+Math.cos(a)*rr,z=PZc+Math.sin(a)*rr;const r=0.45+0.6*api.rng();
 const b=api.icosphereRock(r,0.55,1).scale(1,0.7,1).translate(x-CX,L(x,z)+r*0.25,z-CZ);rocks=rocks?rocks.merge(b):b;}
for(let k=0;k<10;k++){const a=api.rng()*6.283,rr=PR*(1.5+1.5*api.rng());const x=PXc+Math.abs(Math.cos(a))*rr,z=PZc+Math.sin(a)*rr*1.3;const r=0.3+0.5*api.rng();
 const b=api.icosphereRock(r,0.6,1).scale(1,0.65,1).translate(x-CX,L(x,z)+r*0.2,z-CZ);rocks=rocks?rocks.merge(b):b;}
api.add(rocks,{finish:'rock',color:'#8a8277',roughness:0.9,surface:{layers:[{kind:'moss',amount:0.45,mask:{up:0.6,noise:0.5}},{kind:'grime',amount:0.3}]}});
const pool=api.cylinder(PR*1.05,PR*1.05,0.1,28).scale(1,1,1.25).translate(PXc-CX,ground+0.35,PZc-CZ);
api.add(pool,{preset:'water',waterKind:'pond',color:'#5f8f8a',roughness:0.05});
// buried anchors: the object keeps its frame (x/z centred on cx/cz, lowest point 20 m down)
for(const sx of[-1,1])for(const sz of[-1,1])api.add(api.box(0.01,0.01,0.01).translate(sx*30,-20,sz*(ZW/2+4)),{finish:'rock',color:'#777777'});
api.autoColliders('trimesh');
return api.build();

himal-crag.source:
const S=params.size,H=params.height,TP=params.top,N=params.res,SW=params.spur,ZT=params.spurTop,ZF=S/2*0.97;
function ss(a,b,x){let t=(x-a)/(b-a);t=t<0?0:(t>1?1:t);return t*t*(3-2*t);}
function hgt(x,z){const a=Math.atan2(z,x);const r0=Math.sqrt(x*x+z*z)/(S/2);const r=r0*(1+0.15*api.noise2(Math.cos(a)*1.6+3.1,Math.sin(a)*1.6-1.7)+0.05*api.noise2(x*0.12,z*0.12));let h;if(r<TP)h=H;else{const t=Math.min(1,(r-TP)/(1-TP));let f;if(t<0.35){f=1-0.75*Math.pow(t/0.35,1.25);}else{f=0.25*Math.pow(1-(t-0.35)/0.65,1.7);}h=H*f;const cliff=t<0.35?1:0.3;h+=Math.sin(h*1.25)*0.55*cliff;h+=1.4*api.fbm2(x*0.07+5,z*0.07,4)*Math.min(1,t*12)*(1-t*0.6);if(t>=1)h=0;}
 // the stair spur: a rock rib on the south face that the long stair climbs
 if(SW>0&&z>0){const u=(z-ZT)/(ZF-ZT);const line=H*(1-Math.min(1,Math.max(0,u)))-0.35;const ax=Math.abs(x);const m=1-ss(SW,SW*2.6+4,ax);const shoulder=line-Math.max(0,ax-SW)*1.1+0.8*api.noise2(x*0.3,z*0.3);if(u<1.02)h=Math.max(h,Math.min(ax<SW?line:shoulder,H)*(ax<SW?1:m)+(ax<SW?0:h*(1-m)));}
 return Math.max(0,Math.min(H,h));}
const hf=api.heightfield(N,N,S,S,hgt);
hf.vertexColor(function(x,y,z){const n=api.noise2(x*0.3,z*0.3);if(y>H-0.05)return api.mix('#7a7f4e','#8f8a62',0.5+0.5*n);if(y<H*0.12)return api.mix('#6f6a52','#857c68',0.5+0.5*n);const b=0.5+0.5*Math.sin(y*2.3+n);return api.mix(params.color,'#a59c8c',b*0.6);});
api.add(hf,{finish:'rock',color:'#ffffff',vertexColors:true,roughness:0.94,surface:{layers:[{kind:'strata',amount:0.5,scale:1.4},{kind:'lichen',amount:0.4},{kind:'moss',amount:0.3,mask:{up:0.7,noise:0.5}},{kind:'grime',amount:0.4}]}});
api.autoColliders('trimesh');
return api.build();

himal-fence.source:
const L=params.length,H=params.height,rng=api.rng;
const wood={finish:'oak',color:params.color,roughness:0.9,surface:{layers:[{kind:'grime',amount:0.45},{kind:'lichen',amount:0.25},{kind:'edgeWear',amount:0.3}]}};
const rope={preset:'fabric',color:'#8a7a5c',roughness:1};
const n=Math.max(2,Math.round(L/2)+1);const step=L/(n-1);let P=null,R=null;
for(let i=0;i<n;i++){const x=-L/2+i*step;const h=H*(0.95+rng()*0.1);const p=api.cylinder(0.045,0.065,h,7).displace((a,b,c)=>0.008*api.noise3(a*20,b*6+i,c*20)).rotate((rng()-0.5)*4,rng()*60,(rng()-0.5)*4).translate(x,h/2,0);P=P?P.merge(p):p;
 for(const ry of [H*0.45,H*0.85]){const t=api.torus(0.06,0.012).rotate(90,0,0).translate(x,ry,0);R=R?R.merge(t):t;}}
for(const ry of [H*0.45,H*0.85]){const pts=[];for(let k=0;k<=12;k++){const u=k/12;const x=-L/2+u*L;const sag=0.04*Math.sin(Math.PI*((u*(n-1))%1));pts.push([x,ry-sag,0.07]);}
 const r=api.tube(pts,0.03,6);P.merge(r);}
api.add(P,wood);api.add(R,rope);
api.collider({kind:'box',halfExtents:[L/2,H/2,0.08],offset:[0,H/2,0]});
return api.build();

himal-field-wall.source:
const L=params.length,H=params.height,T=params.thickness,rng=api.rng;const F=Math.max(0,Math.min(4,params.footing||0));
const m1={finish:'stone',color:params.color,roughness:0.95,surface:{layers:[{kind:'lichen',amount:0.35},{kind:'grime',amount:0.4}]}};
const m2={finish:'stone',color:api.mix(params.color,'#6e6152',0.4),roughness:0.95,surface:{layers:[{kind:'lichen',amount:0.35},{kind:'grime',amount:0.4}]}};
let A=null,B=null;
function put(m,alt){if(alt){B=B?B.merge(m):m;}else{A=A?A.merge(m):m;}}
const capH=0.16;const courses=Math.max(2,Math.round((H-capH)/0.26));const ch=(H-capH)/courses;
for(let c=0;c<courses;c++){const tc=T*(1-0.35*c/courses);let x=-L/2+(c%2)*0.18;const y=c*ch+ch/2;
 while(x<L/2-0.05){let sl=0.32+rng()*0.32;if(x+sl>L/2)sl=L/2-x;if(sl<0.12)break;const sh=ch*(0.85+rng()*0.25);
  const s=api.box(sl*0.96,sh,tc*(0.88+rng()*0.14)).rotate((rng()-0.5)*6,(rng()-0.5)*8,(rng()-0.5)*8).translate(x+sl/2,y,(rng()-0.5)*0.05);
  put(s,rng()<0.4);x+=sl;}}
const tt=T*0.62;let x=-L/2;
while(x<L/2-0.05){let sl=0.12+rng()*0.1;if(x+sl>L/2)sl=L/2-x;if(sl<0.06)break;const s=api.box(sl*0.92,capH+0.08*rng(),tt).rotate(0,0,(rng()-0.5)*14).translate(x+sl/2,H-capH/2,0);put(s,rng()<0.5);x+=sl;}
if(F>0.01){const n=Math.max(1,Math.round(F/0.4));const fh=F/n;const k=Math.max(3,Math.min(Math.ceil(L/0.7),Math.floor(80/n)));const FT=T*1.18;const xs=-L/2-0.06,xe=L/2+0.06;
 for(let c=0;c<n;c++){let fx=xs+(c%2)*(L/k)*0.45;if(c%2){const s0=api.box((fx-xs)*0.95,fh,FT).translate((xs+fx)/2,-F+c*fh+fh/2,0);put(s0,false);}
  while(fx<xe-0.05){let sl=(L/k)*(0.75+rng()*0.5);if(fx+sl>xe)sl=xe-fx;if(sl<0.15){sl=xe-fx;}
   const sh=c===0?fh:fh*(0.9+rng()*0.16);const y=c===0?-F+sh/2:-F+c*fh+fh/2;
   const s=api.box(sl*0.95,sh,FT*(0.92+rng()*0.16));
   if(c===0)s.rotate(0,(rng()-0.5)*6,0);else s.rotate((rng()-0.5)*7,(rng()-0.5)*10,(rng()-0.5)*7);
   s.translate(fx+sl/2,y,(rng()-0.5)*0.08);put(s,rng()<0.55);fx+=sl;}}}
api.add(A,m1);if(B)api.add(B,m2);
api.collider({kind:'box',halfExtents:[L/2,(H+F)/2,T/2],offset:[0,(H-F)/2,0]});
return api.build();

himal-foam.source:
const R=params.radius, L=params.length, D=params.drop, W=params.width;
let mesh=null;
const slope=Math.atan2(D,L)*180/Math.PI;
function blob(x,y,z,sx,sz,yaw,tilt){
  const b=api.sphere(1,1).scale(sx,0.045,sz).displace((a,c,d)=>0.1*Math.min(sx,sz)*api.noise3(a*3+x*0.7,c*3,d*3+z*0.7)).rotate(0,0,tilt).rotate(0,yaw,0).translate(x,y,z);
  if(mesh){mesh.merge(b);}else{mesh=b;}
}
if(params.mode==='streak'){
  for(let i=0;i<26;i++){
    const u=api.rng();
    const x=u*L;
    const z=(api.rng()-0.5)*W*(1-0.4*u);
    blob(x,-D*u+0.03,z,0.7+api.rng()*1.5,0.07+api.rng()*0.16,(api.rng()-0.5)*10,-slope);
  }
}else{
  for(let i=0;i<42;i++){
    const a=(i/42)*Math.PI*2+api.rng()*0.12;
    if(api.rng()<0.18){continue;}
    const r=R*(0.72+api.rng()*0.28);
    blob(Math.cos(a)*r,api.rng()*0.03,Math.sin(a)*r,0.45+api.rng()*0.6,0.22+api.rng()*0.35,-(a*180/Math.PI+90),0);
  }
  for(let i=0;i<24;i++){
    const r=R*0.66*Math.sqrt(api.rng());
    const a=api.rng()*Math.PI*2;
    blob(Math.cos(a)*r,api.rng()*0.03,Math.sin(a)*r,0.2+api.rng()*0.5,0.15+api.rng()*0.35,api.rng()*180,0);
  }
}
api.add(mesh,{color:params.color,roughness:0.75,opacity:0.92,emissive:'#ffffff',emissiveIntensity:0.06});
return api.build();

himal-goat.source:
const coat=params.coat; const hd=params.headDown*80; const o=api.rng()*10;
function col(x,y,z){
  if(coat==='white'){return y<0.22?'#cfc4b0':'#efe9dd';}
  if(coat==='tan'){return y<0.22?'#6e5034':api.mix('#b88a55','#d9b98a',Math.max(0,api.noise3(x*3+o,y*3,z*3)));}
  if(coat==='black'){return y<0.3?'#1c1815':'#332b25';}
  return api.noise3(x*3.5+o,y*3.5,z*3.5)>0.05?'#2a221c':'#ece6da';
}
const coatM=api.sphere(1,1).scale(0.44,0.18,0.16).displace((x,y,z)=>0.012*api.noise3(x*6+o,y*6,z*6)).translate(0,0.6,0);
coatM.merge(api.sphere(1,1).scale(0.2,0.19,0.15).translate(0.26,0.61,0));
const legs=[[0.28,0.09],[0.28,-0.09],[-0.3,0.09],[-0.3,-0.09]];
for(const L of legs){coatM.merge(api.tube([[L[0],0.56,L[1]],[L[0]+0.015,0.28,L[1]],[L[0],0.02,L[1]]],0.033,5));}
coatM.merge(api.cone(0.025,0.09,4).rotate(0,0,50).translate(-0.45,0.72,0));
const head=api.tube([[0.32,0.66,0],[0.42,0.8,0],[0.48,0.92,0]],0.062,6);
head.merge(api.sphere(1,1).scale(0.13,0.085,0.075).rotate(0,0,-25).translate(0.56,0.95,0));
head.merge(api.sphere(1,0).scale(0.06,0.05,0.05).translate(0.66,0.9,0));
head.merge(api.cone(0.025,0.1,4).rotate(180,0,0).translate(0.65,0.82,0));
const horns=api.tube([[0.52,1.01,0.035],[0.47,1.1,0.05],[0.39,1.13,0.065]],0.016,4);
horns.merge(api.tube([[0.52,1.01,-0.035],[0.47,1.1,-0.05],[0.39,1.13,-0.065]],0.016,4));
for(const sd of [1,-1]){head.merge(api.sphere(1,0).scale(0.07,0.015,0.03).rotate(0,25*sd,-10).translate(0.5,0.99,0.08*sd));}
head.translate(-0.32,-0.66,0).rotate(0,0,-hd).translate(0.32,0.66,0);
horns.translate(-0.32,-0.66,0).rotate(0,0,-hd).translate(0.32,0.66,0);
coatM.merge(head);
coatM.vertexColor(col);
api.add(coatM,{color:'#ffffff',roughness:0.95,vertexColors:true});
api.add(horns,{color:'#6e604c',roughness:0.6});
api.collider({kind:'box',halfExtents:[0.45,0.38,0.15],offset:[0.05,0.4,0]});
return api.build();

himal-gravel-bar.source:
const L=params.length||14, W=params.width||5, H=params.height||0.45;
const gravel={finish:'gravel',color:'#9a9488',roughness:0.95,surface:{layers:[{kind:'tone',amount:0.5,scale:2},{kind:'wet',amount:0.5,mask:{height:[0,0.12]}}]}};
const peb={finish:'stone',color:'#8e887d',roughness:0.85,surface:{layers:[{kind:'tone',amount:0.5},{kind:'lichen',amount:0.15}]}};
const hf=api.heightfield(48,24,L,W,(x,z)=>{const u=x/(L/2), w=z/(W/2); const r=u*u+w*w; if(r>=1) return 0; return H*Math.pow(1-r,0.7)*(1+0.15*api.noise2(x*0.8,z*0.8))+0.03*api.noise2(x*6,z*6);});
api.add(hf,gravel);
let m=null; const n=Math.round(L*W*0.45);
for(let i=0;i<n;i++){ const a=api.rng()*6.283, rr=Math.sqrt(api.rng())*0.92; const x=Math.cos(a)*rr*L/2, z=Math.sin(a)*rr*W/2; const r=0.06+Math.pow(api.rng(),3)*0.28; const y=H*Math.pow(Math.max(0,1-rr*rr),0.7); const s=api.sphere(r,0).scale(1.3,0.6,1).displace((px,py,pz)=>0.12*r*api.noise3(px*9,py*9,pz*9)).rotate(0,api.rng()*180,0).translate(x,y+r*0.2,z); m=m?m.merge(s):s; }
if(m) api.add(m,peb);
api.autoColliders('trimesh');
return api.build();

himal-house.source:
// Ladakhi / Tibetan houses: 8 hand-tuned types, varied by seed. Front faces +z. Local y=0 is the ground at the door;
// the foundation runs down to -found so the house steps onto sloping ground (the entity y = ground top - found).
const TYPE=params.type, R=function(){return api.rng();};
const pick=function(a){return a[Math.floor(R()*a.length)];};
const found=params.found;
let w=params.width,d=params.depth,fl=Math.max(1,Math.round(params.floors));
if(TYPE==='hut'){w=Math.min(w,6.2);d=Math.min(d,5.2);fl=1;}
const pl=TYPE==='hut'?0.45:0.7+R()*0.5;            // plinth above the door ground
const gh=TYPE==='teahouse'?3.2:3.0, uh=2.75+R()*0.2; // ground / upper storey heights
const s=Math.tan((3+R()*2.2)*Math.PI/180);        // batter: walls lean in by s per metre
// ------------------------------------------------------------------ palette
let wall=params.wall;if(wall==='auto')wall=TYPE==='hut'?'stone':pick(['white','white','ochre','stone','redband','white','ochre']);
if(TYPE==='noble')wall=R()<0.6?'redband':'white';
const plaster=wall==='ochre'?api.mix('#e8b580','#efc596',R()):(wall==='stone'?'#a39886':api.mix('#ebe5d8','#f5f1e8',R()));
const trimCol=wall==='redband'?'#7a2418':pick(['#6e2a1d','#5b3b24','#2f4e44','#7a5a2c','#7b2a24','#384e6a']);
const bandCol=wall==='redband'?'#6a1d16':pick(['#2a1a14','#3a1a13','#221c1a','#43211a']);
const stoneCol=api.mix(params.stoneColor,pick(['#9a8f80','#857a6c','#a09482']),0.5);
const M={
 stone:{finish:'stone',color:stoneCol,roughness:0.95,surface:{layers:[{kind:'tone',amount:0.5,scale:0.7},{kind:'grime',amount:0.45},{kind:'lichen',amount:0.25}]}},
 plaster:{finish:wall==='stone'?'stone':'plaster',color:plaster,roughness:0.93,surface:{layers:[{kind:'tone',amount:0.45,scale:1.1},{kind:'streaks',amount:0.6},{kind:'grime',amount:0.55,mask:{height:[0,0.2]}}]}},
 lime:{finish:'plaster',color:'#efeae0',roughness:0.92,surface:{layers:[{kind:'tone',amount:0.35},{kind:'streaks',amount:0.4},{kind:'grime',amount:0.35}]}},
 band:{finish:'plaster',color:bandCol,roughness:0.9,surface:{layers:[{kind:'tone',amount:0.4},{kind:'streaks',amount:0.35}]}},
 oak:{finish:'oak',color:params.woodColor,roughness:0.82,surface:{layers:[{kind:'edgeWear',amount:0.45},{kind:'grime',amount:0.35}]}},
 paint:{finish:'oak',color:trimCol,roughness:0.72,surface:{layers:[{kind:'edgeWear',amount:0.55},{kind:'grime',amount:0.3}]}},
 deco:{finish:'oak',color:'#ffffff',vertexColors:true,roughness:0.7},
 dark:{finish:'plaster',color:'#1a1614',roughness:0.85},
 glass:{color:'#141b20',roughness:0.12,metalness:0.3},
 soil:{finish:'soil',color:'#7d6a52',roughness:1},
 twig:{finish:'bark',color:'#4b3b2c',roughness:1},
 log:{finish:'bark',color:'#6a5440',roughness:0.95},
