    for(let j=0;j<nf;j++){const u=nf===1?(R()-0.5)*L*0.3:-(L-1.8)/2+j*(L-1.8)/(nf-1);
     if(face===df&&gi===0&&v===V[0]&&Math.abs(u-du)<(opts.wide?2.4:1.4))continue;
     if(rab&&face===rab.face&&v===topV&&isTop&&Math.abs(u-rab.u)<rab.bw/2+0.7)continue;
     if(face!==0&&R()<(side?0.3:0.35))continue;
     win(B,face,u,cy,side?ww*0.9:ww,wh,style);}}}}
 if(rab){const B=topV.B;const cy=B.y0+(topV.n-1)*uh+(topV.base===0&&topV.n===1?1.4:1.35)+(floors===1?0:0);rabsal(B,rab.face,rab.u,cy,rab.bw);}
 const tops=V.map(function(v,i){return top(v.B,opts.parapet);});
 return {V:V,B0:B0,tops:tops,H:Hh,du:du,df:df};}
function rabsal(B,face,u,cy,bw){const bh=1.45,pj=0.6;const P=[];
 P.push(['paint',rb(bw+0.34,0.16,pj+0.14,0.04).translate(0,-bh/2-0.08,pj/2)]);
 const nb=Math.max(4,Math.round(bw/0.45));
 for(let k=0;k<nb;k++)P.push(['oak',bx(0.11,0.11,pj+0.24).translate(-bw/2+0.1+k*(bw-0.2)/(nb-1),-bh/2-0.21,pj/2)]);
 P.push(['glass',bx(bw-0.1,bh-0.1,0.03).translate(0,0,pj-0.02)]);
 for(const sx of[-1,1])P.push(['oak',bx(0.05,bh-0.1,pj).translate(sx*(bw/2-0.06),0,pj/2)]);
 const nm=Math.max(3,Math.round(bw/0.55));
 for(let k=0;k<=nm;k++)P.push(['oak',bx(0.08,bh,0.1).translate(-bw/2+0.04+k*(bw-0.08)/nm,0,pj)]);
 for(let k=0;k<nm;k++){const x=-bw/2+0.04+(k+0.5)*(bw-0.08)/nm;P.push(['oak',bx(0.03,bh*0.55,0.03).translate(x,bh*0.15,pj+0.02)]);}
 P.push(['oak',bx(bw,0.05,0.06).translate(0,bh*0.12,pj+0.02)]);
 P.push(['paint',rb(bw,0.3,0.08,0.02).translate(0,-bh/2+0.2,pj+0.02)]);
 P.push(['oak',bx(bw+0.1,0.08,0.1).translate(0,bh/2,pj)]);
 lintel(P,bw,bh/2+0.14,pj-0.1);
 for(let q=0;q<P.length;q++)put(P[q][0],B.place(face,P[q][1],u,cy));}
// ------------------------------------------------------------------ the types
let H=null;const extras=[];
const propsAt=[]; // [x,z,yaw] spots by the front wall for props
function frontSpots(B,n){const L=B.len(0,pl+0.5);for(let k=0;k<n;k++)propsAt.push([B.cx+(R()-0.5)*(L-2),B.cz+B.hz(pl)+0.9+R()*0.5]);}
if(TYPE==='village'){
 H=house(0,0,w,d,fl,{mode:R()<0.35?2:0,rabsal:{face:0,u:(R()-0.5)*w*0.3,bw:2.2+R()*0.8},stoneLower:R()<0.5});
}else if(TYPE==='hut'){
 H=house(0,0,w,d,1,{});
}else if(TYPE==='farm'){
 H=house(0,0,w,d,fl,{mode:R()<0.4?1:0,stoneLower:R()<0.6,rabsal:R()<0.4?{face:0,u:(R()<0.5?-1:1)*w*0.18,bw:1.9}:null});
 // byre annex on one side: single storey rubble, flat roof with hay
 const sx=R()<0.5?-1:1;const aw=4+R()*1.2, ad=d*0.8;const ax=sx*(w/2+aw/2+0.1);
 put('stone',rb(aw+0.4,found+0.3,ad+0.4,0.12).translate(ax,(0.3-found)/2,-d*0.08));
 const BA=soft(ax,-d*0.08,aw,ad,0.3,2.3,'stone',0.03);
 const T=top(BA,0.3);
 door(BA,0,0,0.3,false);
 hay(ax-0.6,T.yp+0.1,-d*0.08,1.0);hay(ax+0.7,T.yp+0.1,-d*0.08-0.4,0.8);
 // courtyard wall round the front yard, with a gate gap
 const yd=4.5+R()*2.5;const x0=-w/2-(sx<0?aw:0)-0.4,x1=w/2+(sx>0?aw:0)+0.4,z0=d/2+0.3,z1=z0+yd;
 const gx=(R()-0.5)*w*0.4;
 rubbleWall(x0,z0,x0,z1,1.3);rubbleWall(x1,z0,x1,z1,1.3);rubbleWall(x0,z1,gx-1.1,z1,1.3);rubbleWall(gx+1.1,z1,x1,z1,1.3);
 for(const s2 of[-1,1])put('lime',rb(0.6,1.8,0.6,0.1,2).translate(gx+s2*1.25,0.9-found/2,z1).scale(1,1,1));
 propsAt.push([x1-1.2,z0+1.2]);propsAt.push([x0+1.2,z1-1.2]);
 extras.push(function(){hay(x0+1.6,0,z0+1.8,0.9);});
}else if(TYPE==='noble'){
 const f2=Math.max(3,fl);H=house(0,0,w,d,f2,{mode:R()<0.4?1:0,rabsal:{face:0,u:0,bw:Math.min(w*0.42,4.2)},stoneLower:true,parapet:0.6});
 // a second, smaller rabsal on a side
 {const B=H.V[H.V.length-1].B;rabsal(B,R()<0.5?1:3,0,B.y0+B.h-1.5,2.2);}
 // walled front courtyard with a gate and a roofed gateway
 const yd=6+R()*2;const z0=d/2+0.3,z1=z0+yd;
 rubbleWall(-w/2-0.3,z0,-w/2-0.3,z1,2.1);rubbleWall(w/2+0.3,z0,w/2+0.3,z1,2.1);rubbleWall(-w/2-0.3,z1,-1.4,z1,2.1);rubbleWall(1.4,z1,w/2+0.3,z1,2.1);
 const GB=soft(0,z1,3.2,1.2,0,2.9,'plaster',0.02);top(GB,0.35);
 put('dark',bx(1.6,2.2,1.3).translate(0,1.1,z1));
 propsAt.push([w/2-1.3,z0+1.2]);propsAt.push([-w/2+1.3,z0+1.5]);
}else if(TYPE==='terrace'){
 H=house(0,0,w,d,Math.max(2,fl),{mode:1,rabsal:R()<0.5?{face:0,u:(R()-0.5)*w*0.3,bw:2.0}:null});
}else if(TYPE==='teahouse'){
 H=house(0,0,w,d,Math.max(2,fl),{mode:R()<0.5?2:0,wide:true,du:0,rabsal:R()<0.5?{face:0,u:(R()<0.5?-1:1)*w*0.22,bw:2.2}:null});
 // awning on four posts over the shop front, two benches, a low table and a signboard
 const zf=d/2+0.25,aw=Math.min(w-1,6.5),ad=2.6;const C=pick(['#b8322a','#2f5fa8','#c98a24','#3d6a4a']);
 for(const sx of[-1,1]){put('oak',rb(0.14,2.45,0.14,0.03).translate(sx*aw/2,pl+1.22-0.05,zf+ad));}
 put('oak',rb(aw+0.2,0.1,0.12,0.02).translate(0,pl+2.45,zf+ad));
 const cl=api.plane(aw+0.4,ad+0.2,6,3).rotate(-14,0,0).translate(0,pl+2.75,zf+ad/2).warp(function(x,y,z){return [x,y-0.06*Math.sin(Math.PI*(x+aw/2)/aw),z];}).vertexColor(function(x,y,z){return Math.floor((x+10)/0.55)%2?C:'#efe8d6';});
 put('cloth',cl);
 const bdz=zf+1.0;for(const sx of[-1,1]){const bxp=sx*(aw/2-1.2);
  put('oak',rb(1.8,0.07,0.36,0.02).translate(bxp,pl+0.45,bdz+0.8));
  for(const lx of[-0.75,0.75])put('oak',rb(0.08,0.42,0.3,0.02).translate(bxp+lx,pl+0.21,bdz+0.8));}
 put('stone',rb(aw+0.4,pl+found,ad+0.6,0.1).translate(0,(pl-found)/2,zf+ad/2+0.1));
 put('oak',rb(1.2,0.06,0.6,0.02).translate(0,pl+0.55,bdz+0.8));put('oak',rb(0.1,0.5,0.1,0.02).translate(0,pl+0.27,bdz+0.8));
 put('paint',rb(2.2,0.45,0.06,0.02).translate(0,pl+3.25,zf+0.08));
 barrel(-aw/2+0.4,pl,zf+0.5);
}else if(TYPE==='lshape'){
 H=house(0,0,w,d,fl,{mode:0,rabsal:R()<0.6?{face:0,u:-w*0.2,bw:2.1}:null,du:w*0.22});
 // wing at right angles, one storey lower, its roof a terrace reached by an outside stair
 const sx=R()<0.5?-1:1;const ww2=Math.max(4.5,d*0.7),wd=d*0.95+3;const wx=sx*(w/2+ww2/2-0.05),wz=1.5;
 put('stone',rb(ww2+0.5,pl+found,wd+0.5,0.14).translate(wx,(pl-found)/2,wz));
 const WB=soft(wx,wz,ww2,wd,pl,gh,'plaster');const T=top(WB,0.5);
 for(let k=0;k<2;k++)win(WB,0,(k-0.5)*ww2*0.4,pl+1.5,0.85,0.95,1);win(WB,sx>0?1:3,0,pl+1.5,0.8,0.95,1);
 // outside stone stair up the wing's front wall
 const n=Math.round((pl+gh+0.4)/0.25);const zf=wz+wd/2+0.25;
 for(let k=0;k<n;k++)put('stone',rb(0.9,0.25*(k+1)+found,0.34,0.04).translate(wx-sx*(ww2/2-0.6)+sx*k*0.3*0,(0.25*(k+1)-found)/2,zf+0.34*(n-k)-0.2));
 propsAt.push([wx,zf+0.9]);
}else if(TYPE==='farmstead'){
 H=house(0,0,w,d,Math.max(2,fl),{mode:R()<0.5?1:0,stoneLower:true,rabsal:{face:0,u:0,bw:2.6}});
 // two outbuildings (byre and store) round a walled courtyard in front
 const yd=8+R()*2;const z0=d/2+0.4,z1=z0+yd;
 const ob=[[-w/2-0.2,z0+yd*0.45,4.2,yd*0.8],[w/2+0.2,z0+yd*0.4,4.6,yd*0.7]];
 for(let i=0;i<2;i++){const o=ob[i];const ox=o[0]+(i?1:-1)*o[2]/2;
  put('stone',rb(o[2]+0.4,found+0.3,o[3]+0.4,0.12).translate(ox,(0.3-found)/2,o[1]));
  const BB=soft(ox,o[1],o[2],o[3],0.3,i?2.6:2.3,i?'plaster':'stone',0.03);const T=top(BB,0.3);
  door(BB,i?3:1,0,0.3,false);if(i===0){hay(ox,T.yp+0.1,o[1]-0.8,1.1);hay(ox+0.3,T.yp+0.1,o[1]+1.1,0.85);}
  else{win(BB,1,0,1.7,0.6,0.6,1);}}
 rubbleWall(-w/2-0.2-4.2,z1,-1.5,z1,1.5);rubbleWall(1.5,z1,w/2+0.2+4.6,z1,1.5);
 for(const s2 of[-1,1])put('lime',rb(0.7,2.0,0.7,0.12,2).translate(s2*1.6,1.0-found/2,z1));
 propsAt.push([0.5,z0+2.5]);propsAt.push([-2.5,z1-1.4]);
 extras.push(function(){hay(2.6,0,z0+3.2,1.0);woodpile(-1.5,z0+1.0,0,1.6);});
}else{ H=house(0,0,w,d,fl,{}); }
// ------------------------------------------------------------------ roof life and props by seed
const TOPS=H.tops;const TT=TOPS[TOPS.length-1];
twigs(TT,TYPE==='hut'?1:0.65);if(TOPS.length>1)twigs(TOPS[0],0.4);
roofFlags(TT,TYPE==='terrace'||TYPE==='noble'||(TYPE==='farmstead'));
if(TYPE!=='hut'&&R()<0.6)woodpile(TT.cx-TT.ex*0.35,TT.cz+TT.ez*0.6,0,1.4);
// sangkang incense burner on a roof corner
put('lime',api.lathe([[0,0],[0.3,0],[0.3,0.35],[0.22,0.42],[0.26,0.62],[0.18,0.66],[0,0.66]],10).translate(TT.cx+(R()<0.5?-1:1)*(TT.ex-0.6),TT.yp+0.12,TT.cz-TT.ez+0.6));
// front props: a few of woodpile, ladder, barrel, marigold pots, laundry line
frontSpots(H.B0,3);
const kinds=['wood','ladder','barrel','pots','laundry'];
const nProps=TYPE==='hut'?2:3+Math.floor(R()*2);
for(let k=0;k<nProps&&k<propsAt.length+2;k++){const sp=propsAt[k%propsAt.length];const kind=kinds[Math.floor(R()*kinds.length)];
 const x=sp[0],z=sp[1];
 if(kind==='wood')woodpile(x,z,R()*20-10,1.2+R()*0.8);
 else if(kind==='ladder'){const B=H.B0;ladder(B.cx+(R()-0.5)*B.w*0.6,0,B.cz+B.hz(pl)+0.95,0,Math.min(3.2,pl+gh-0.2));}
 else if(kind==='barrel')barrel(x,0,z);
 else if(kind==='pots'){for(let j=0;j<3;j++)marigolds(x+j*0.5-0.5,0,z+(R()-0.5)*0.3);}
 else laundry(x,0,z+0.3,R()*30-15,2.6+R());}
// marigolds on the parapet of most houses
if(R()<0.6){for(let j=0;j<2+Math.floor(R()*3);j++)marigolds(TT.cx-TT.ex*0.6+j*0.55,TT.yp+TT.PH,TT.cz+TT.ez);}
for(const f of extras)f();
if(flagM.length){let F=flagM[0];for(let k=1;k<flagM.length;k++)F.merge(flagM[k]);put('cloth',F);}
// symmetric buried anchors keep the main block on the entity origin whatever the yard or wing adds
let ex=0,ez=0;for(const k in acc){const b=acc[k].bounds();ex=Math.max(ex,Math.abs(b.min[0]),Math.abs(b.max[0]));ez=Math.max(ez,Math.abs(b.min[2]),Math.abs(b.max[2]));}
for(const sx of[-1,1])for(const sz of[-1,1])put('stone',bx(0.01,0.01,0.01).translate(sx*ex,-found+0.005,sz*ez));
for(const k in acc)api.add(acc[k],M[k]);
const B0=H.B0;const hh=(B0.y0+B0.h+0.8+found)/2;
api.collider({kind:'box',halfExtents:[B0.w/2+0.25,hh,B0.d/2+0.25],offset:[0,hh,0]});
return api.build();

himal-mani-wall.source:
const L = params.length, H = params.height, W = params.width;
const F = Math.max(0, Math.min(4, params.footing || 0));
const stone = {finish:'stone', color:'#857d71', roughness:0.92, surface:{layers:[{kind:'tone',amount:0.4},{kind:'grime',amount:0.5},{kind:'moss',amount:0.4,mask:{up:0.4,noise:0.5}},{kind:'lichen',amount:0.3}]}};
const white = {finish:'plaster', color:'#e9e3d6', roughness:0.85, surface:{layers:[{kind:'grime',amount:0.45},{kind:'streaks',amount:0.3}]}};
const slates = [
  {finish:'stone', color:'#5d6166', roughness:0.75, surface:{layers:[{kind:'runes',amount:0.12,color:'#c9b68a'},{kind:'lichen',amount:0.2},{kind:'edgeWear'}]}},
  {finish:'stone', color:'#6e6a62', roughness:0.8, surface:{layers:[{kind:'runes',amount:0.12,color:'#c9b68a'},{kind:'lichen',amount:0.25},{kind:'edgeWear'}]}},
  {finish:'stone', color:'#4f5456', roughness:0.7, surface:{layers:[{kind:'runes',amount:0.12,color:'#c9b68a'},{kind:'edgeWear'}]}}
];
const body = api.roundedBox(L, H, W, 0.12, 3).translate(0, H/2, 0);
body.displace(function(x,y,z){ return 0.045*api.noise3(x*2.2, y*2.2, z*2.2) + 0.02*api.noise3(x*7, y*7, z*7); });
api.add(body, stone);
api.add(api.roundedBox(L*0.98, 0.08, W*0.9, 0.03, 1).translate(0, H + 0.03, 0), stone);
const n = Math.max(2, Math.floor((L - 1.0) / 0.32));
const step = (L - 1.0) / n;
for (let row = -1; row <= 1; row += 2) {
  for (let i = 0; i < n; i++) {
    const x = -L/2 + 0.5 + step*(i + 0.5) + (api.rng()-0.5)*0.05;
    const h = 0.32 + api.rng()*0.14, w = 0.26 + api.rng()*0.04;
    const t = api.box(w, h, 0.05);
    t.rotate(row*(10 + api.rng()*6), (api.rng()-0.5)*6, (api.rng()-0.5)*5);
    t.translate(x, H + 0.05 + h/2 - 0.03, row*W*0.17);
    api.add(t, slates[Math.floor(api.rng()*3)]);
  }
}
for (let e = -1; e <= 1; e += 2) {
  const cap = api.roundedBox(0.5, H + 0.45, W + 0.1, 0.08, 2).translate(e*(L/2 - 0.25), (H + 0.45)/2, 0);
  api.add(cap, white);
  api.add(api.lathe([[0,0],[0.22,0],[0.18,0.14],[0.06,0.3],[0,0.32]], 14).translate(e*(L/2 - 0.25), H + 0.45, 0), white);
}
if (F > 0.01) {
  const rng = api.rng; let FM = null;
  const nc = Math.max(1, Math.round(F / 0.42)); const fh = F / nc;
  const k = Math.max(3, Math.min(Math.ceil(L / 0.8), Math.floor(64 / nc)));
  const FW = W + 0.24, xs = -L/2 - 0.12, xe = L/2 + 0.12;
  for (let c = 0; c < nc; c++) {
    let fx = xs + (c % 2) * (L / k) * 0.45;
    if (c % 2) { const s0 = api.box((fx - xs) * 0.95, fh, FW).translate((xs + fx) / 2, -F + c*fh + fh/2, 0); FM = FM ? FM.merge(s0) : s0; }
    while (fx < xe - 0.05) {
      let sl = (L / k) * (0.75 + rng() * 0.5); if (fx + sl > xe) sl = xe - fx; if (sl < 0.18) sl = xe - fx;
      const sh = c === 0 ? fh : fh * (0.9 + rng() * 0.16);
      const y = c === 0 ? -F + sh/2 : -F + c*fh + fh/2;
      const s = api.box(sl * 0.95, sh, FW * (0.93 + rng() * 0.14));
      if (c === 0) s.rotate(0, (rng()-0.5)*5, 0); else s.rotate((rng()-0.5)*6, (rng()-0.5)*8, (rng()-0.5)*6);
      s.translate(fx + sl/2, y, (rng()-0.5)*0.08);
      FM = FM ? FM.merge(s) : s; fx += sl;
    }
  }
  api.add(FM, stone);
}
api.collider({kind:'box', halfExtents:[L/2, (H + 0.3 + F)/2, W/2], offset:[0, (H + 0.3 - F)/2, 0]});
return api.build();

himal-monastery.source:
const R=function(){return api.rng();};
const M={
 white:{finish:'plaster',color:'#efe9dc',roughness:0.92,surface:{layers:[{kind:'tone',amount:0.35,scale:1.5},{kind:'streaks',amount:0.55},{kind:'grime',amount:0.45,mask:{height:[0,0.2]}}]}},
 red:{finish:'plaster',color:params.redColor,roughness:0.9,surface:{layers:[{kind:'tone',amount:0.45,scale:1.2},{kind:'streaks',amount:0.45},{kind:'grime',amount:0.35}]}},
 band:{finish:'plaster',color:'#3a1712',roughness:0.95,surface:{layers:[{kind:'tone',amount:0.5,scale:0.6}]}},
 stone:{finish:'stone',color:'#8a8174',roughness:0.94,surface:{layers:[{kind:'tone',amount:0.4},{kind:'grime',amount:0.4},{kind:'lichen',amount:0.25}]}},
 oak:{finish:'oak',color:'#5d3b22',roughness:0.8,surface:{layers:[{kind:'edgeWear',amount:0.4},{kind:'grime',amount:0.3}]}},
 paint:{finish:'oak',color:'#8e2a1c',roughness:0.7,surface:{layers:[{kind:'edgeWear',amount:0.5}]}},
 dark:{finish:'plaster',color:'#1c1816',roughness:0.85},
 glass:{color:'#161c21',roughness:0.15,metalness:0.25},
 gold:{finish:'brass',color:'#d9a441',metalness:0.92,roughness:0.28},
 cloth:{finish:'fabric',color:'#2a2422',roughness:1,doubleSided:true},
 soil:{finish:'soil',color:'#7d6a52',roughness:1}
};
const acc={};
function put(k,m){if(acc[k])acc[k].merge(m);else acc[k]=m;}
function bx(a,b,c){return api.box(a,b,c);}
function rb(a,b,c,r){return api.roundedBox(a,b,c,Math.min(r,a/2.2,b/2.2,c/2.2),1);}
// a battered block: footprint w x d at y0, walls lean in by tp over height h; returns helpers to dress its faces
function block(cx,cz,w,d,y0,h,tp,mat){
 put(mat,rb(w,h,d,0.08).translate(0,h/2,0).warp(function(x,y,z){const k=1-tp*y/h;return [cx+x*k,y0+y,cz+z*k];}));
 const B={cx:cx,cz:cz,w:w,d:d,y0:y0,h:h,tp:tp};
 B.f=function(y){return 1-tp*(y-y0)/h;};
 B.place=function(face,m,u,cy){const side=face===1||face===3;const a=Math.atan((side?w:d)*tp/2/h)*180/Math.PI;const dist=(side?w:d)*B.f(cy)/2;
  m.rotate(-a,0,0).translate(u,0,dist).rotate(0,[0,90,180,-90][face],0).translate(cx,cy,cz);return m;};
 // the dark parapet band (penbey) with gilded mirrors, a timber cornice, a white parapet
 B.top=function(band,mirrors){const yT=y0+h, wT=w*B.f(yT), dT=d*B.f(yT);
  put('band',bx(w*B.f(yT-band/2)+0.08,band,d*B.f(yT-band/2)+0.08).translate(cx,yT-band/2,cz).warp(function(x,y,z){const k=B.f(y)/B.f(yT-band/2);return [cx+(x-cx)*k,y,cz+(z-cz)*k];}));
