const s=params.size, bed=params.bed;
const o=api.rng()*50;
const sx=s*(0.45+api.rng()*0.15), sy=s*(0.33+api.rng()*0.12), sz=s*(0.36+api.rng()*0.12);
const k=2.7/s;
let m=api.sphere(1,3).scale(sx,sy,sz);
m.displace((x,y,z)=>{
  const n=api.noise3(x*k+o,y*k,z*k)*s*0.1+api.noise3(x*k*3.3+o,y*k*3.3,z*k*3.3)*s*0.025;
  const t=(y+sy)/bed; const f=t-Math.floor(t);
  return n-f*f*bed*0.3;
});
m.warp((x,y,z)=>[x+params.lean*Math.max(0,y),y<0?y*0.35:y,z]);
const mat={preset:'stone',finish:'rock',color:params.color,roughness:0.93,surface:{layers:[{kind:'strata',amount:0.45,scale:bed},{kind:'lichen',amount:0.35},{kind:'grime',amount:0.35},{kind:'edgeWear',amount:0.25}]}};
api.add(m,mat);
const base=-sy*0.35;
let sc=null;
for(let i=0;i<10;i++){
  const a=api.rng()*Math.PI*2; const r=0.85+api.rng()*0.6; const pr=s*(0.04+api.rng()*0.06);
  const p=api.sphere(1,0).rotate(api.rng()*360,api.rng()*360,0).scale(pr*(0.8+api.rng()*0.5),pr*0.6,pr).translate(Math.cos(a)*sx*r,base+pr*0.3,Math.sin(a)*sz*r);
  if(sc){sc.merge(p);}else{sc=p;}
}
api.add(sc,mat);
api.collider({kind:'box',halfExtents:[sx*0.8,sy*0.62,sz*0.8],offset:[0,sy*0.3,0]});
return api.build();

