for(const sx of [-1,1]){const p=api.cylinder(0.05,0.075,H,8).displace((a,b,c)=>0.006*api.noise3(a*20,b*5+sx,c*20)).translate(sx*S/2,H/2,0);P=P?P.merge(p):p;
 const f=api.sphere(0.07,1).translate(sx*S/2,H+0.04,0);P.merge(f);
 api.collider({kind:'cylinder',halfHeight:H/2,radius:0.08,offset:[sx*S/2,H/2,0]});}
api.add(P,wood);
const ly=u=>H-0.15-sag*4*u*(1-u);
const pts=[];for(let k=0;k<=24;k++){const u=k/24;pts.push([-S/2+u*S,ly(u),0]);}
api.add(api.tube(pts,0.008,4),cord);
const G=[null,null,null,null,null];
for(let i=0;i<n;i++){const u=(i+0.5)/n;const x=-S/2+u*S;const y=ly(u);const w=Math.min(0.3,S/n*0.85),h=0.34;const ph=rng()*6;
 const f=api.plane(w,h,3,4).rotate(90,0,0).warp((a,b,c)=>[a,b,c+0.035*Math.sin(a*18+b*9+ph)+0.04*(h/2-b)]).rotate(0,0,(rng()-0.5)*6).translate(x,y-h/2-0.01,0);
 const k=i%5;G[k]=G[k]?G[k].merge(f):f;}
for(let k=0;k<5;k++)if(G[k])api.add(G[k],mats[k]);
return api.build();

