walls.merge(RB1(t,h,d-2*t,0.04).translate(-w/2+t/2,pl+h/2,0));
walls.merge(RB1(t,h,d-2*t,0.04).translate(w/2-t/2,pl+h/2,0));
const dw=0.8,dh=1.5,sw=(w-dw)/2;
walls.merge(RB1(sw,h,t,0.04).translate(-(dw/2+sw/2),pl+h/2,d/2-t/2));
walls.merge(RB1(sw,h,t,0.04).translate(dw/2+sw/2,pl+h/2,d/2-t/2));
walls.merge(RB1(dw,h-dh,t,0.04).translate(0,pl+dh+(h-dh)/2,d/2-t/2));
api.add(rough(tap(walls),0.012),stone);
const fr=RB1(dw+0.5,0.14,t+0.08,0.03).translate(0,pl+dh+0.07,d/2-t/2);
fr.merge(RB1(0.1,dh,0.1,0.02).translate(-dw/2+0.05,pl+dh/2,d/2-0.02));
fr.merge(RB1(0.1,dh,0.1,0.02).translate(dw/2-0.05,pl+dh/2,d/2-0.02));
api.add(fr,oak);
const prof=[[0,0],[0.32,0],[0.35,0.05],[0.35,0.1],[0.3,0.13],[0.3,0.77],[0.35,0.8],[0.35,0.86],[0.3,0.9],[0.06,0.97],[0,0.98]];
api.add(api.lathe(prof,32).translate(0,pl+0.15,-0.1),paint);
const bands=api.torus(0.305,0.022).rotate(90,0,0).translate(0,pl+0.4,-0.1);
bands.merge(api.torus(0.305,0.022).rotate(90,0,0).translate(0,pl+0.6,-0.1));
bands.merge(api.cylinder(0.04,0.04,h-0.1,10).translate(0,pl+h/2,-0.1));
api.add(bands,brass);
const a=24,ar=a*Math.PI/180,hs=d/2+0.45,pL=hs/Math.cos(ar),yt=pl+h;
const rf=RB1(w+0.9,0.1,pL,0.03).rotate(a,0,0).translate(0,yt+0.12+Math.tan(ar)*hs/2,hs/2);
rf.merge(RB1(w+0.9,0.1,pL,0.03).rotate(-a,0,0).translate(0,yt+0.12+Math.tan(ar)*hs/2,-hs/2));
api.add(rf,slate);
const gh=d/2*0.94;
const g=api.extrude([[-gh,0],[gh,0],[0,Math.tan(ar)*gh]],t).rotate(0,90,0);
const gab=g.clone().translate(-(w/2-t/2)*0.94,yt,0);gab.merge(g.clone().translate((w/2-t/2)*0.94,yt,0));
api.add(gab,stone);
const tim=api.cylinder(0.07,0.07,w+1,10).rotate(0,0,90).translate(0,yt+0.14+Math.tan(ar)*hs,0);
tim.merge(RB1(w+0.95,0.12,0.08,0.02).translate(0,yt+0.07,hs-0.04));
tim.merge(RB1(w+0.95,0.12,0.08,0.02).translate(0,yt+0.07,-hs+0.04));
const u=[[-0.2,0],[0.2,0],[0.2,0.3],[0.15,0.3],[0.15,0.05],[-0.15,0.05],[-0.15,0.3],[-0.2,0.3]];
const wat=api.box(0.3,0.03,L).translate(0,0.2,0).rotate(0,90,0);
for(const s of [-1,1]){const yb=s<0?pl+0.15:0.35;const cx=s*(w/2+0.3+L/2);
 tim.merge(api.extrude(u,L).rotate(0,90,0).translate(cx,yb,0));
 api.add(wat.clone().translate(cx,yb,0),water);
 for(const k of [-0.35,0.35]){const px=cx+k*L;tim.merge(RB1(0.1,yb,0.1,0.02).translate(px,yb/2,0.12));tim.merge(RB1(0.1,yb,0.1,0.02).translate(px,yb/2,-0.12));}}
api.add(tim,oak);
api.add(api.lathe([[0,0],[0.07,0],[0.05,0.12],[0.09,0.2],[0.03,0.32],[0,0.36]],16).translate(0,yt+0.2+Math.tan(ar)*hs,0),brass);
api.collider({kind:'box',halfExtents:[w/2+0.3,(pl+h)/2,d/2+0.3],offset:[0,(pl+h)/2,0]});
return api.build();

himal-range.source:
const H = params.height || 200;
const S = params.size || 480;
const N = Math.max(24, Math.min(200, Math.round(params.res || params.resolution || 108)));
const v = Math.round(params.variant || 0);
const snowLine = 0.4;
const haze = params.haze === undefined ? 0.3 : params.haze;
const ox = api.rng() * 100 + 11.3, oz = api.rng() * 100 + 37.9, os = api.rng() * 100 + 5.1;
const half = S / 2;
function clamp01(a) { return a < 0 ? 0 : (a > 1 ? 1 : a); }
function sstep(a, b, x) { const t = clamp01((x - a) / (b - a)); return t * t * (3 - 2 * t); }
function pn(a, b, p) { return Math.pow(Math.pow(Math.abs(a), p) + Math.pow(Math.abs(b), p), 1 / p); }
function bump(wx, wz, cx, cz, sx, sz, hgt) { const d = pn((wx - cx) / sx, (wz - cz) / sz, 4); const q = Math.max(0, 1 - d); return hgt * Math.pow(q, 1.4); }
function shape(wx, wz) {
  if (v === 1) {
    const d = pn(wx * 0.62, wz * 1.55, 4);
    const q = Math.max(0, 1 - d * 1.04);
    return Math.pow(q, 1.35) * (0.9 + 0.1 * api.noise2(wx * 2.2 + ox, oz));
  }
  if (v === 2) {
    const a = bump(wx, wz, 0.05, 0.0, 0.8, 0.8, 1.0);
    const b = bump(wx, wz, -0.42, 0.12, 0.55, 0.6, 0.78);
    const c = bump(wx, wz, 0.45, -0.1, 0.5, 0.55, 0.7);
    const k = 10;
    return Math.log(Math.exp(k * a) + Math.exp(k * b) + Math.exp(k * c)) / k - Math.log(3) / k * (1 - Math.max(a, b, c)) * 0.0;
  }
  const d = pn(wx, wz, 6);
  const q = Math.max(0, 1 - d * 1.05);
  return Math.pow(q, 1.4);
}
function heightAt(x, z) {
  const nx = x / half, nz = z / half;
  const wx = nx + 0.07 * api.fbm2(nx * 1.7 + ox, nz * 1.7 + oz, 3);
  const wz = nz + 0.07 * api.fbm2(nx * 1.7 + oz + 50, nz * 1.7 + ox - 20, 3);
  const base = Math.max(0, shape(wx, wz));
  let r = 0, amp = 1, f = 3.1, tot = 0;
  for (let i = 0; i < 4; i++) {
    const n = api.noise2(wx * f + ox + i * 17.1, wz * f + oz - i * 9.7);
    const c = 1 - Math.abs(n);
    r += amp * c * c; tot += amp; amp *= 0.5; f *= 2.07;
  }
  r = r / tot;
  let h = base * (0.82 + 0.36 * (r - 0.45)) + 0.05 * Math.pow(base, 0.5) * api.fbm2(wx * 9 + os, wz * 9 - os, 3);
  const edge = sstep(0.82, 0.99, pn(nx, nz, 8));
  h = h * (1 - edge);
  return Math.max(0, h) * H;
}
const mesh = api.heightfield(N, N, S, S, heightAt);
const e = S / N;
const d2 = 3 * e;
const lowA = '#4a433d', lowB = '#6b625a', scree = '#8b8275', hiA = '#3f3934', hiB = '#5a524b', baseGround = '#5c5448';
const snow = '#f2f4f8', glacier = '#c3d6e6', hazeCol = '#c8cbd6';
mesh.vertexColor(function (x, y, z) {
  const t = y / H;
  const gx = (heightAt(x + e, z) - heightAt(x - e, z)) / (2 * e);
  const gz = (heightAt(x, z + e) - heightAt(x, z - e)) / (2 * e);
  const g = Math.sqrt(gx * gx + gz * gz);
  const avg = (heightAt(x + d2, z) + heightAt(x - d2, z) + heightAt(x, z + d2) + heightAt(x, z - d2)) * 0.25;
  const cv = (avg - y) / d2;
  const hollow = sstep(0.02, 0.1, cv);
  const ridge = sstep(0.03, 0.12, -cv);
  const n1 = clamp01(0.5 + 0.5 * api.noise2(x * 5 / S + ox, z * 5 / S + oz));
  const n2 = api.noise2(x * 11 / S + os, z * 11 / S - oz);
  const sl = snowLine + 0.06 * api.fbm2(x * 6 / S + ox, z * 6 / S + oz, 3) - 0.05 * hollow;
  let low = api.mix(lowA, lowB, n1);
  const screeAmt = sstep(0.3, 0.5, g) * (1 - sstep(0.78, 0.98, g)) * sstep(-0.01, 0.05, cv) * sstep(-0.3, 0.35, n2) * (1 - sstep(sl - 0.06, sl + 0.04, t));
  low = api.mix(low, scree, 0.65 * screeAmt);
  low = api.mix(baseGround, low, sstep(0.02, 0.12, t));
  const high = api.mix(hiA, hiB, n1);
  let col = api.mix(low, high, sstep(sl - 0.06, sl + 0.1, t));
  const u = x * 0.83 + z * 0.56;
  const m = api.noise2(u / (S * 0.011) + os, y / (H * 0.075) + oz);
  const mask = api.noise2(x * 3.3 / S + 7.1 + ox, y * 4.7 / H + 3.3) + 0.5 * api.noise2(z * 3.1 / S - 4.2, y * 6.1 / H - 2.6 + os);
  const dstreak = sstep(0.42, 0.7, m) * sstep(0.05, 0.4, mask) * sstep(0.5, 1.1, g);
  col = api.mix(col, hiA, 0.5 * dstreak);
  const above = sstep(sl - 0.015, sl + 0.035, t);
  const steep = sstep(1.25, 1.75, g);
  let lie = (1 - steep) * (1 - 0.6 * ridge);
  lie = Math.max(lie, 0.9 * hollow * (1 - sstep(1.05, 1.45, g)));
  const sstreak = sstep(0.35, 0.75, m) * sstep(-0.2, 0.3, mask);
  const ledge = sstep(0.45, 0.8, api.noise2(x * 9 / S + os, y / (H * 0.018) + ox)) * (1 - sstep(1.25, 1.75, g));
  const steepSnow = steep * (0.55 * sstreak + 0.55 * ledge) * (1 - 0.5 * ridge);
  let snowAmt = above * clamp01(lie + steepSnow);
  const gully = (1 - above) * sstep(0.08, 0.18, cv) * sstep(sl - 0.22, sl - 0.03, t) * sstep(0.25, 0.65, m) * 0.7;
  snowAmt = Math.max(snowAmt, gully);
  // a snow mantle above the line: thins only on the steepest faces and the dark rock streaks
  snowAmt = Math.max(snowAmt, above * 0.85 * (1 - sstep(1.7, 2.6, g)) * (1 - 0.7 * dstreak) * (1 - 0.5 * ridge));
  col = api.mix(col, snow, clamp01(snowAmt));
  const gl = sstep(sl - 0.04, sl + 0.03, t) * (1 - sstep(0.3, 0.55, g)) * sstep(0.01, 0.06, cv) * sstep(-0.2, 0.3, api.noise2(x * 5 / S + os, z * 5 / S - os));
  col = api.mix(col, glacier, 0.8 * gl);
  const hz = haze * (0.35 + 0.65 * (1 - clamp01(t))) * 0.45;
  return api.mix(col, hazeCol, clamp01(hz));
});
api.add(mesh, { vertexColors: true, roughness: 0.92, metalness: 0 });
api.collider({ kind: 'box', halfExtents: [half * 0.5, H * 0.3, half * 0.5], offset: [0, H * 0.3, 0] });
return api.build();

himal-stack.source:
const s=params.size,rng=api.rng;
if(params.variant===0){
 const bark={finish:'bark',color:'#5e4a3a',roughness:0.95,surface:{layers:[{kind:'lichen',amount:0.2}]}};
 const grain={finish:'oak',color:'#b89870',roughness:0.85,surface:{layers:[{kind:'grime',amount:0.3}]}};
 const slate={finish:'stone',color:'#77726a',roughness:0.95,surface:{layers:[{kind:'lichen',amount:0.4}]}};
 const W=1.8*s,len=0.8*s,r=0.075*s;let B=null,E=null;const rows=5;
 for(let j=0;j<rows;j++){const nlog=Math.floor(W/(2*r))-(j%2);const x0=-((nlog-1)*r);
  for(let i=0;i<nlog;i++){const rr=r*(0.85+rng()*0.25);const x=x0+i*2*r,y=rr+j*r*1.75,dz=(rng()-0.5)*0.08*s;
   const l=api.cylinder(rr,rr,len,6).rotate(90,rng()*20,0).translate(x,y,dz);B=B?B.merge(l):l;
   for(const e of [-1,1]){const c=api.cylinder(rr*0.92,rr*0.92,0.01,5).rotate(90,0,0).translate(x,y,dz+e*len/2);E=E?E.merge(c):c;}}}
 api.add(B,bark);api.add(E,grain);
 const top=rows*r*1.75+r*0.6;let C=null;for(let k=0;k<3;k++){const c=api.roundedBox(0.7*s,0.06*s,len*1.05,0.02,1).rotate(0,(rng()-0.5)*14,(rng()-0.5)*6).translate(-W/3+k*W/3,top,0);C=C?C.merge(c):c;}
 api.add(C,slate);
 api.collider({kind:'box',halfExtents:[W/2,top/2,len/2],offset:[0,top/2,0]});
}else{
 const hay={color:'#b39556',roughness:1,surface:{layers:[{kind:'tone',amount:0.5},{kind:'grime',amount:0.35,mask:{height:[0,0.4]}}]}};
 const wood={finish:'oak',color:'#6e5c48',roughness:0.9};
 const prof=[[0,0],[1.0,0],[1.12,0.4],[1.08,1.1],[0.85,1.8],[0.45,2.35],[0.1,2.6],[0,2.62]].map(q=>[q[0]*s,q[1]*s]);
 const h=api.lathe(prof,18).displace((a,b,c)=>0.04*s*api.noise3(a*6,b*14,c*6)+0.015*s*api.noise3(a*30,b*40,c*30));
 api.add(h,hay);
 api.add(api.cylinder(0.035*s,0.045*s,0.7*s,6).translate(0,2.85*s,0),wood);
 api.add(api.torus(0.55*s,0.03*s).rotate(90,0,0).translate(0,1.95*s,0),{preset:'fabric',color:'#7c6a4a',roughness:1});
 api.collider({kind:'cylinder',halfHeight:1.3*s,radius:1.05*s,offset:[0,1.3*s,0]});
}
return api.build();

himal-stair.source:
const H=params.height,L=params.length,W=params.width,F=Math.max(1,params.flights|0),LL=params.landing;
const runP=Math.max(2,(L-(F-1)*LL)/F),riseP=H/F;
const n=Math.max(3,Math.round(riseP/0.17));const rz=riseP/n,tr=runP/n;
const ang=Math.atan2(riseP,runP)*180/Math.PI;const slen=Math.sqrt(runP*runP+riseP*riseP);
const stone={finish:'stone',color:params.color,roughness:0.92,surface:{layers:[{kind:'tone',amount:0.5},{kind:'grime',amount:0.5},{kind:'lichen',amount:0.35},{kind:'edgeWear',amount:0.6}]}};
const wallM={finish:'stone',color:api.mix(params.color,'#6e675d',0.4),roughness:0.95,surface:{layers:[{kind:'tone'},{kind:'moss',amount:0.35,mask:{noise:0.5}},{kind:'grime'}]}};
const cope={finish:'plaster',color:'#e6dfd2',roughness:0.85,surface:{layers:[{kind:'streaks',amount:0.4},{kind:'edgeWear'}]}};
const pw=0.35,ph=0.55;let x=0,y=0;
for(let f=0;f<F;f++){
 const x0=x,y0=y;
 for(let s=0;s<n;s++){const top=y0+(s+1)*rz;const j=(api.rng()-0.5)*0.02;
  api.add(api.box(tr+0.05,rz+0.35,W).translate(x0+s*tr+tr/2,top-(rz+0.35)/2+j,0),stone);}
 const cx=x0+runP/2,cy=y0+riseP/2;const a=ang*Math.PI/180;const off=0.75;
 const sx=cx+Math.sin(a)*off,sy=cy-Math.cos(a)*off;
 api.add(api.box(slen,1.2,W+0.1).rotate(0,0,ang).translate(sx,sy,0),wallM);
 for(const side of [-1,1]){const z=side*(W/2+pw/2);
  api.add(api.box(slen,ph+0.3,pw).rotate(0,0,ang).translate(cx,cy+ph/2,z),wallM);
  api.add(api.roundedBox(slen,0.1,pw+0.08,0.03,1).rotate(0,0,ang).translate(cx,cy+ph+0.2,z),cope);}
 api.collider({kind:'box',halfExtents:[slen/2,0.3,W/2],offset:[cx+Math.sin(a)*0.3,cy-Math.cos(a)*0.3+0.02,0],rotation:[0,0,ang]});
 x=x0+runP;y=y0+riseP;
 if(f<F-1){const lx=x+LL/2;
  api.add(api.roundedBox(LL+0.1,0.45,W+0.2,0.06,1).translate(lx,y-0.225,0),stone);
  const ph2=Math.max(0.5,y-0.4);
  api.add(api.cylinder(Math.min(LL,W)*0.36,Math.min(LL,W)*0.5,ph2,10).translate(lx,ph2/2,0),wallM);
  for(const side of [-1,1]){const z=side*(W/2+pw/2);
   api.add(api.box(LL+0.1,ph,pw).translate(lx,y+ph/2,z),wallM);
   api.add(api.roundedBox(LL+0.2,0.1,pw+0.08,0.03,1).translate(lx,y+ph+0.05,z),cope);}
  api.collider({kind:'box',halfExtents:[LL/2+0.05,0.225,W/2],offset:[lx,y-0.225,0]});
  api.collider({kind:'cylinder',halfHeight:ph2/2,radius:Math.min(LL,W)*0.4,offset:[lx,ph2/2,0]});
  x+=LL;}
}
return api.build();

himal-suspension-bridge.source:
function RB1(a,b,c,r){return api.roundedBox(a,b,c,r,1);}
const L=params.span,W=params.width,F=params.footing,TH=params.towerHeight,DS=params.deckSag;
const half=L/2;const D=F+1.4;
const stone={finish:'stone',color:params.stoneColor,roughness:0.92,surface:{layers:[{kind:'grime',amount:0.5},{kind:'lichen',amount:0.4},{kind:'edgeWear',amount:0.5}]}};
const oak={finish:'oak',color:'#6a4e34',roughness:0.85,surface:{layers:[{kind:'grime',amount:0.4},{kind:'edgeWear',amount:0.4}]}};
const plankMat={finish:'oak',color:'#7a6045',roughness:0.9,surface:{layers:[{kind:'grime',amount:0.5},{kind:'scratches',amount:0.3}]}};
const rope={finish:'fabric',color:'#857457',roughness:1};
const steel={finish:'black-metal',color:'#3a3a3a',roughness:0.6,metalness:0.7};
function deckY(x){const u=x/half;return D-DS*(1-u*u);}
const yT=D+TH-0.45;const yL=D-DS+1.15;const a=L*0.55;
const ch=Math.cosh(half/a)-1;
function cabY(x){return yL+(yT-yL)*(Math.cosh(x/a)-1)/ch;}
const cz=W/2+0.35;
// towers
for(const sx of [-1,1]){
 const tx=sx*(half+0.9);
 const base=RB1(2.8,D,W+1.8,0.14,2).translate(tx,D/2,0);
 base.displace((x,y,z)=>0.03*api.noise3(x*2,y*2,z*2));
 api.add(base,stone);
 api.add(RB1(3.0,0.25,W+2.0,0.08,2).translate(tx,D-0.12,0),stone);
 let tw=null;
 for(const s of [-1,1]){
  const p=RB1(0.34,TH,0.34,0.05,2).translate(tx,D+TH/2,s*cz);
  tw=tw?tw.merge(p):p;
  const brace=RB1(0.16,1.3,0.16,0.03,1).rotate(0,0,sx*35).translate(tx-sx*0.0,D+0.6,s*cz);
  tw.merge(RB1(0.5,0.4,0.5,0.06,2).translate(tx,D+0.2,s*cz));
 }
 tw.merge(RB1(0.4,0.32,W+1.5,0.06,2).translate(tx,D+TH-0.16,0));
 tw.merge(RB1(0.3,0.24,W+0.9,0.05,2).translate(tx,D+TH*0.62,0));
 tw.merge(RB1(1.3,0.14,W+2.3,0.05,2).translate(tx,D+TH+0.07,0));
 api.add(tw,oak);
 api.add(api.extrude([[-0.7,0],[0.7,0],[0,0.55]],W+2.2).rotate(0,0,0).translate(tx,D+TH+0.14,0),{finish:'roof-tile',color:'#5b4a3c',roughness:0.9});
 // anchor
 const ax=sx*(half+5.5);
 const anc=RB1(1.6,1.4,W+1.6,0.15,2).translate(ax,F-0.5,0);
 api.add(anc,stone);
 for(const s of [-1,1]){
  api.add(api.tube([[sx*(half+0.9),yT,s*cz],[ax,F+0.2,s*cz]],0.035,6),steel);
 }
 api.collider({kind:'box',halfExtents:[1.4,D/2,W/2+0.9],offset:[tx,D/2,0]});
}
// main cables, hangers, handrails
const N=48;
for(const s of [-1,1]){
 const pts=[];
 for(let i=0;i<=N;i++){const x=-(half+0.9)+(L+1.8)*i/N;pts.push([x,Math.min(cabY(Math.min(Math.abs(x),half))+0,yT),s*cz]);}
 api.add(api.tube(pts,0.04,6),steel);
 const rail=[];
 for(let i=0;i<=N;i++){const x=-half+L*i/N;rail.push([x,deckY(x)+1.0,s*(W/2+0.08)]);}
 api.add(api.tube(rail,0.025,5),rope);
 let hg=null;
 for(let x=-half+1;x<half-0.5;x+=1.1){
  const h=api.tube([[x,cabY(x),s*cz],[x,deckY(x)+1.0,s*(W/2+0.08)],[x,deckY(x)-0.02,s*(W/2+0.06)]],0.012,4);
  hg=hg?hg.merge(h):h;
 }
 if(hg)api.add(hg,rope);
}
// stringers
for(const s of [-1,1]){
 const st=[];for(let i=0;i<=N;i++){const x=-(half+0.3)+(L+0.6)*i/N;st.push([x,deckY(x)-0.1,s*(W/2-0.12)]);}
 api.add(api.tube(st,0.06,6),oak);
}
// planks
let pl=null;
const np=Math.floor(L/0.24);
for(let i=0;i<np;i++){
 const x=-half+0.12+i*(L-0.24)/(np-1);
 const slope=-2*DS*x/(half*half);
 const ang=Math.atan(slope)*180/Math.PI;
 const w=W*(0.96+api.rng()*0.06);
 const p=RB1(0.2,0.055,w,0.015,1).rotate(0,(api.rng()-0.5)*3,ang+(api.rng()-0.5)*1.5).translate(x,deckY(x)-0.02+(api.rng()-0.5)*0.015,(api.rng()-0.5)*0.05);
 pl=pl?pl.merge(p):p;
}
api.add(pl,plankMat);
// prayer flags along cables
const cols=['#2f5f9e','#ece6d6','#b8342c','#3f7a45','#d9b23a'];
const fm=[null,null,null,null,null];
let k=0;
for(const s of [-1,1]){
 for(let x=-half+0.6;x<half-0.4;x+=0.55){
  const y=cabY(x);
  const f=api.box(0.3,0.38,0.012).rotate((api.rng()-0.5)*20,90+(api.rng()-0.5)*25,(api.rng()-0.5)*8).translate(x,y-0.24,s*cz);
  const c=k%5;fm[c]=fm[c]?fm[c].merge(f):f;k++;
 }
}
for(let c=0;c<5;c++)if(fm[c])api.add(fm[c],{finish:'fabric',color:cols[c],roughness:0.95,doubleSided:true});
// deck colliders
const seg=12;
for(let i=0;i<seg;i++){
 const x0=-half+L*i/seg,x1=-half+L*(i+1)/seg;
 const y0=deckY(x0),y1=deckY(x1);
 const len=Math.hypot(x1-x0,y1-y0);
 const ang=Math.atan2(y1-y0,x1-x0)*180/Math.PI;
 api.collider({kind:'box',halfExtents:[len/2+0.02,0.05,W/2],offset:[(x0+x1)/2,(y0+y1)/2-0.03,0],rotation:[0,0,ang]});
}
