himal-temple.source:
function RB1(a,b,c,r){return api.roundedBox(a,b,c,r,1);}
const W=params.width||7, D=params.depth||7, H=params.height||5.5;
const stone={finish:'stone',color:'#8d8579',roughness:0.92,surface:{layers:[{kind:'grime',amount:0.5},{kind:'lichen',amount:0.3},{kind:'edgeWear',amount:0.4}]}};
