const mats={stone:stone,plaster:plaster,red:red,wood:wood,dark:dark,brass:brass,paint:paint,slate:slate,cloth:cloth};
const acc={};
function put(k,m){ if(acc[k]) acc[k].merge(m); else acc[k]=m; }
function align(m){ const b=m.bounds(); if(b.max[0]>0.6) m.rotate(0,45,0); return m; }
function taper(w,h,d,t){ return align(api.cylinder(0.7071*t,0.7071,1,4)).scale(w,h,d); }
put('stone',RB1(W+3.2,0.55,D+3.2,0.1).translate(0,0.275,0));
put('stone',RB1(W+1.8,0.5,D+1.8,0.1).translate(0,0.8,0));
const y0=1.05;
put('stone',RB1(2.4,0.25,0.4,0.04).translate(0,0.675,D/2+1.1));
put('stone',RB1(2.6,0.3,0.45,0.04).translate(0,0.15,D/2+1.82));
