put('red',taper(W*0.935+0.1,0.7,D*0.935+0.1,0.99).translate(0,y0+H-0.35,0));
const tw=W*0.93, td=D*0.93, yb=y0+H+0.02;
for(let i=0;i<Math.floor(tw/0.45);i++){ const x=-tw/2+0.25+i*0.45; put('wood',RB1(0.16,0.16,0.4,0.03).translate(x,yb,td/2+0.1)); put('wood',RB1(0.16,0.16,0.4,0.03).translate(x,yb,-td/2-0.1)); }
for(let i=0;i<Math.floor(td/0.45);i++){ const z=-td/2+0.25+i*0.45; put('wood',RB1(0.4,0.16,0.16,0.03).translate(tw/2+0.1,yb,z)); put('wood',RB1(0.4,0.16,0.16,0.03).translate(-tw/2-0.1,yb,z)); }
put('dark',RB1(tw+0.7,0.18,td+0.7,0.05).translate(0,y0+H+0.2,0));
put('slate',RB1(tw+1.3,0.22,td+1.3,0.1).translate(0,y0+H+0.4,0));
const yR=y0+H+0.51;
put('red',RB1(W*0.4,1.1,D*0.4,0.06).translate(0,yR+0.55,0));
put('brass',RB1(W*0.6,0.12,D*0.6,0.04).translate(0,yR+1.16,0));
put('brass',align(api.cone(0.7071,1,4)).scale(W*0.56,1.4,D*0.56).translate(0,yR+1.22+0.7,0));
put('brass',api.lathe([[0,0],[0.25,0],[0.3,0.1],[0.18,0.25],[0.28,0.45],[0.12,0.7],[0.2,0.9],[0.05,1.2],[0,1.3]],16).translate(0,yR+2.5,0));
const dh=[[0,0],[0.16,0],[0.18,0.6],[0.21,0.66],[0.05,0.85],[0,0.95]];
for(const sx of [-1,1]) for(const sz of [-1,1]) put('brass',api.lathe(dh,12).translate(sx*(tw/2+0.35),yR,sz*(td/2+0.35)));
const zf=D/2*(1-0.07*1.3/H);
put('dark',RB1(1.8,2.7,0.2,0.04).translate(0,y0+1.35,zf));
put('paint',RB1(1.35,2.35,0.12,0.03).translate(0,y0+1.2,zf+0.1));
put('brass',api.sphere(0.06,1).translate(-0.18,y0+1.3,zf+0.18));
put('brass',api.sphere(0.06,1).translate(0.18,y0+1.3,zf+0.18));
put('wood',RB1(2.4,0.22,0.5,0.04).translate(0,y0+2.82,zf+0.12));
put('slate',RB1(2.8,0.14,1.0,0.05).translate(0,y0+3.05,zf+0.4));
function win(x,y,z,r){ const f=RB1(1.0,1.2,0.14,0.03); const l=RB1(1.4,0.14,0.3,0.03).translate(0,0.7,0.05); const s=RB1(1.15,0.08,0.22,0.02).translate(0,-0.62,0.05); for(const p of [[f,'dark'],[l,'wood'],[s,'wood']]) put(p[1],p[0].rotate(0,r,0).translate(x,y,z)); }
const yw=y0+3.0, k=1-0.07*3.0/H;
win(-2.1,yw,D/2*k+0.02,0); win(2.1,yw,D/2*k+0.02,0);
win(-1.7,yw,-D/2*k-0.02,180); win(1.7,yw,-D/2*k-0.02,180);
win(W/2*k+0.02,yw,-1.5,90); win(W/2*k+0.02,yw,1.5,90);
win(-W/2*k-0.02,yw,-1.5,-90); win(-W/2*k-0.02,yw,1.5,-90);
const wp=[[0.02,0],[0.17,0],[0.19,0.04],[0.19,0.08],[0.17,0.09],[0.17,0.81],[0.19,0.82],[0.19,0.86],[0.17,0.9],[0.02,0.9]];
const wheel=api.lathe(wp,16).scale(1,0.95,1);
const band=api.cylinder(0.177,0.177,0.55,16);
function gal(len,ox,oz,r){ const parts=[]; parts.push(['stone',RB1(len,0.3,2.0,0.06).translate(0,0.15,0)]); parts.push(['plaster',RB1(len,2.9,0.4,0.06).translate(0,1.75,0.8)]); parts.push(['red',RB1(len+0.02,0.35,0.44,0.04).translate(0,3.0,0.8)]); parts.push(['wood',RB1(len,0.12,0.5,0.03).translate(0,0.75,0.25)]); parts.push(['wood',RB1(len,0.1,0.5,0.03).translate(0,1.74,0.25)]); const n=Math.floor((len-0.6)/0.55); for(let i=0;i<n;i++){ const x=-((n-1)*0.55)/2+i*0.55; parts.push(['brass',wheel.clone().translate(x,0.82,0.2)]); parts.push(['paint',band.clone().translate(x,1.25,0.2)]); } const np=Math.max(2,Math.round(len/2.4)+1); for(let i=0;i<np;i++){ const x=-len/2+0.2+i*(len-0.4)/(np-1); parts.push(['wood',RB1(0.2,2.65,0.2,0.04).translate(x,1.62,-0.85)]); parts.push(['wood',RB1(0.6,0.15,0.26,0.04).translate(x,2.97,-0.85)]); } parts.push(['wood',RB1(len,0.2,0.22,0.04).translate(0,3.12,-0.85)]); parts.push(['slate',RB1(len+0.4,0.16,2.6,0.06).rotate(-8,0,0).translate(0,3.35,-0.05)]); for(const p of parts) put(p[0],p[1].rotate(0,r,0).translate(ox,0,oz)); const s=Math.sin(r*Math.PI/180), c=Math.cos(r*Math.PI/180); api.collider({kind:'box',halfExtents:[len/2,0.15,1.0],offset:[ox,0.15,oz],rotation:[0,r,0]}); api.collider({kind:'box',halfExtents:[len/2,1.6,0.2],offset:[ox+0.8*s,1.6,oz+0.8*c],rotation:[0,r,0]}); }
const Gx=W/2+2.9, Gz=D/2+2.9;
gal(2*Gx+2.0,0,-Gz,180);
const sl=Gz+D/2, sc=(-Gz+1.0+D/2+1.0)/2;
gal(sl,Gx,sc,90); gal(sl,-Gx,sc,-90);
const px=W/2+1.6, pz=D/2+3.2;
put('stone',api.lathe([[0,0],[0.55,0],[0.5,0.3],[0.3,0.45],[0.25,0.6],[0,0.6]],16).translate(px,0,pz));
put('wood',api.cylinder(0.07,0.1,9,10).translate(px,0.6+4.5,pz));
put('cloth',api.cylinder(0.32,0.34,3.2,14).translate(px,6.6,pz));
put('brass',api.lathe([[0,0],[0.12,0],[0.06,0.3],[0,0.5]],10).translate(px,9.6,pz));
api.collider({kind:'box',halfExtents:[(W+3.2)/2,0.525,(D+3.2)/2],offset:[0,0.525,0]});
api.collider({kind:'box',halfExtents:[W/2,H/2,D/2],offset:[0,y0+H/2,0]});
api.collider({kind:'cylinder',halfHeight:4.8,radius:0.3,offset:[px,4.8,pz]});
for(const key in acc) api.add(acc[key],mats[key]);
return api.build();

himal-terrace-field.source:
function ss(a,b,x){let t=(x-a)/(b-a); t=t<0?0:(t>1?1:t); return t*t*(3-2*t);}
function rx(z){return 25*Math.sin(z*0.011)+12*Math.sin(z*0.029+1);}
function fl(z){return 26*ss(-80,-300,z);}
const TS=1.5, FX=-100, FZ=-40, LIP=params.lip, R=params.relief;
function terr(x,z,d){return ss(46,56,d)*(1-ss(118,138,d))*ss(-80,-58,z)*(1-ss(128,150,z))*(1-(1-ss(62,80,Math.abs(z-FZ)))*ss(-45,-60,x));}
function sz(x){return FZ+2.5*Math.sin(x*0.09)+1.5*Math.sin(x*0.23);}
function H(x,z,P){
 const d=Math.abs(x-rx(z));
 const n=api.fbm2(x*0.011,z*0.011,4);
 const n2=api.fbm2(x*0.05+7,z*0.05-3,2);
 const f=fl(z);
 let s=Math.pow(ss(28,240,d),1.25)*R*(1+0.35*n)*(1-0.3*ss(0,60,x-rx(z)));
 const band=ss(90,140,z)*(1-ss(230,280,z));
 const g=22*ss(12,26+4*n2,d)*band;
 const ero=ss(40,200,d)*8*(n2*0.5+0.5)*(0.5+0.5*n);
 let h=f+s+g+ero+2.2*n2*ss(14,40,d);
 const c=1-ss(7,15+3*n2,d);
 h=h*(1-c)+(f-3)*c;
 // fine erosion: rills down the slopes and small knolls
 h+=ss(20,60,d)*(0.9*api.fbm2(x*0.09,z*0.03,2)+0.3*api.noise2(x*0.31,z*0.31));
 // terraced barley fields cut into both slopes, following the contours
 const T=terr(x,z,d);
 if(T>0.001){const o=0.9*api.noise2(x*0.025,z*0.025);const hn=h+o;const k=Math.floor(hn/TS);const fr=hn/TS-k;const ht=k*TS+TS*ss(0.8,0.97,fr)-o;h=h*(1-T)+(ht-(P?0:1.0))*T;}
 // hanging valley on the west wall: an escarpment with a notch whose floor (LIP) is the lip of the fall
 const az=Math.abs(z-FZ);const wb=1-ss(48,72,az);
 if(wb>0){const notch=1-ss(9,20,az+1.5*api.noise2(x*0.08,1.3));const E=LIP+13*(1-notch)+1.2*api.noise2(x*0.07,z*0.07)-1.0*notch*ss(FX-2,FX-30,x);
  const cl=ss(FX+3,FX-4,x+2*api.noise2(z*0.15,x*0.15))*wb;h=Math.max(h,h*(1-cl)+E*cl);
  const fm=ss(FX+11,FX+6,x)*(1-ss(FX+3.5,FX+1.5,x))*(1-ss(3,7,Math.abs(z-FZ)));h-=1.6*fm;}
 // the stream from the plunge pool to the river
 const xr=rx(FZ);
 if(x>FX+2&&x<xr){const dz=Math.abs(z-sz(x));h-=0.7*(1-ss(1.4,3.2,dz))*ss(FX+2,FX+6,x);}
 return h<-3?-3:h;
}
const CX=params.cx, CZ=params.cz, PW=params.w, PD=params.d, NX=Math.round(PW/0.75)+1, NZ=Math.round(PD/0.75)+1;
const Y=new Array(NX*NZ), FR=new Array(NX*NZ), K=new Array(NX*NZ), TT=new Array(NX*NZ);
for(let j=0;j<NZ;j++){const z=-PD/2+PD*j/(NZ-1);for(let i=0;i<NX;i++){const x=-PW/2+PW*i/(NX-1);const X=CX+x,Z=CZ+z;const d=Math.abs(X-rx(Z));const T=terr(X,Z,d);const q=j*NX+i;TT[q]=T;
 const h=H(X,Z,1);
 if(T<0.35){Y[q]=h-1.6;FR[q]=0;K[q]=0;}else{const o=0.9*api.noise2(X*0.025,Z*0.025);const hn=h+o;const k=Math.floor(hn/TS);Y[q]=h;FR[q]=hn/TS-k;K[q]=k;}}}
function idx(x,z){const i=Math.round((x+PW/2)/PW*(NX-1)),j=Math.round((z+PD/2)/PD*(NZ-1));return Math.min(NZ-1,Math.max(0,j))*NX+Math.min(NX-1,Math.max(0,i));}
const CS=PW/(NX-1),BK=12;let m=null;
for(let bj=0;bj*BK<NZ-1;bj++)for(let bi=0;bi*BK<NX-1;bi++){const i0=bi*BK,i1=Math.min(NX-1,i0+BK),j0=bj*BK,j1=Math.min(NZ-1,j0+BK);let keep=false;
 for(let j=j0;j<=j1&&!keep;j++)for(let i=i0;i<=i1;i++)if(TT[j*NX+i]>=0.3){keep=true;break;}
 if(!keep)continue;const bw=(i1-i0)*CS,bd=(j1-j0)*CS,ox=-PW/2+i0*CS+bw/2,oz=-PD/2+j0*CS+bd/2;
 const b=api.heightfield(i1-i0+1,j1-j0+1,bw,bd,function(x,z){return Y[idx(x+ox,z+oz)];}).translate(ox,0,oz);m=m?m.merge(b):b;}
if(!m)m=api.box(0.05,0.05,0.05).translate(0,-19,0);
for(const sx of[-1,1])for(const sz of[-1,1])m.merge(api.box(0.01,0.01,0.01).translate(sx*PW/2,-19,sz*PD/2));
function hash(k){const s=Math.sin(k*127.1+311.7)*43758.5453;return s-Math.floor(s);}
m.vertexColor(function(x,y,z){const q=idx(x,z);const X=CX+x,Z=CZ+z;const fr=FR[q],k=K[q];
 const v2=api.noise2(X*0.6,Z*0.6)*0.5+0.5, v3=api.noise2(X*2.1,Z*2.1)*0.5+0.5;
 const hk=hash(k+Math.floor((Z+400)/38)*31+Math.floor((X+400)/52)*7);
 let crop=hk<0.45?api.mix('#cdb15e','#bfa050',v2):(hk<0.8?api.mix('#7c973c','#93a64a',v2):api.mix('#7a5f42','#8d7150',v2));
 crop=api.mix(crop,api.mix('#e3cf88','#6f8a36',v3),0.18);
 crop=api.mix(crop,'#6c6a3a',0.35*(1-ss(0.05,0.18,fr)));
 const riser=ss(0.78,0.83,fr)*(1-ss(0.975,0.995,fr));
 const wall=api.mix('#6b645a','#9a8f80',v3);
 const cap=ss(0.965,0.98,fr)*(1-ss(0.99,1,fr));
 return api.mix(api.mix(crop,wall,riser),'#a39a8a',cap*0.6);
});
api.add(m,{finish:'soil',color:'#ffffff',vertexColors:true,roughness:0.95});
api.add(api.box(0.05,0.05,0.05).translate(0,-20,0),{finish:'soil',color:'#ffffff'});
api.autoColliders('trimesh');
return api.build();

himal-terraces.source:
const L=params.length,n=params.steps,d=params.stepDepth,r=params.rise,bow=params.bow,sk=params.skirt;
const bend=function(z){const u=2*z/L;return bow*(1-u*u);};
const stone={finish:'stone',color:'#8a8070',roughness:0.95,surface:{layers:[{kind:'tone',amount:0.5,scale:0.6},{kind:'grime',amount:0.5},{kind:'lichen',amount:0.35},{kind:'moss',amount:0.25,mask:{up:0.4,noise:0.5}}]}};
const coping={finish:'stone',color:'#9a9282',roughness:0.9,surface:{layers:[{kind:'lichen',amount:0.4},{kind:'edgeWear',amount:0.4}]}};
const field={preset:'grass',color:params.barley,roughness:0.9,shader:{bump:'0.05*fbm(p*2.5,3)',color:'base*(0.85+0.3*(0.5+0.5*fbm(p*0.35,3)))'}};
const gold=api.color(params.barley);
for(let i=0;i<n;i++){
 const x0=i*d;
 const yb=i*r-(i===0?sk:0.2);
 const yt=(i+1)*r;
 const h=yt-yb;
 const w=api.plane(h,L,6,Math.max(8,Math.round(L*2)));
 w.rotate(0,0,90);
 w.warp(function(x,y,z){const yy=y+yb+h/2;const t=(yy-yb)/h;return [x0+bend(z)+t*0.35*r,yy,z];});
 w.displace(function(x,y,z){const a=Math.abs(api.noise3(x*2.2,y*3.4,z*1.6));return 0.08*(1-a)-0.03+0.02*api.noise3(x*9,y*9,z*9);});
 api.add(w,stone);
 const cp=[];const seg=Math.max(8,Math.round(L));
 for(let k=0;k<=seg;k++){const z=-L/2+L*k/seg;cp.push([x0+bend(z)+0.35*r+0.1,yt+0.05,z]);}
 api.add(api.tube(cp,0.2,6).displace(function(x,y,z){return 0.04*api.noise3(x*4,y*4,z*4);}),coping);
 const f=api.plane(d-0.2,L,6,Math.max(8,Math.round(L)));
 f.warp(function(x,y,z){return [x0+0.35*r+0.2+(x+(d-0.2)/2)+bend(z),yt-0.05+0.06*api.noise2(x*0.8+i*5,z*0.8),z];});
 f.vertexColor(function(x,y,z){const m=0.5+0.5*api.fbm2(x*0.15,z*0.15,3);return api.mix(api.mix('#7f9a45',params.barley,0.55+0.45*m),'#d6c27a',0.25*Math.max(0,api.noise2(x*0.6,z*0.6)));});
 api.add(f,field);
}
api.autoColliders('trimesh');
return api.build();

himal-tree.source:
const v=params.variant|0, H=params.height, rng=api.rng;
const bark={finish:'bark',color:params.trunkColor,roughness:0.95,surface:{layers:[{kind:'tone',amount:0.4,scale:0.4},{kind:'lichen',amount:0.3}]}};
const C=params.color;
const dark=api.mix(C,'#14200f',0.55), mid=C, lite=api.mix(C,'#d8d27a',v===1?0.12:0.3);
let wood=null;function addWood(m){wood=wood?wood.merge(m):m;}
let cards=null;
// a leaf-cluster card (the renderer cuts leaf clusters out of it): centre p, facing n (outward from the crown), size s;
// shaded by height in the crown and by depth (inner cards darker), so the crown reads as layered masses of leaves
function card(p,n,s,shade,hang){const l=Math.hypot(n[0],n[1],n[2])||1;const nx=n[0]/l,ny=n[1]/l,nz=n[2]/l;
 const tilt=Math.acos(Math.max(-1,Math.min(1,ny)))*180/Math.PI, yaw=Math.atan2(nx,nz)*180/Math.PI;
 const m=api.plane(s,s*(hang?1.5:1)).rotate(0,hang?180:rng()*360,0).rotate(tilt,0,0).rotate(0,yaw,0).translate(p[0],p[1],p[2]);
 const sh=Math.max(0,Math.min(1,shade));
 m.vertexColor(function(x,y,z){const t=Math.max(0,Math.min(1,sh+0.05*(y-p[1])/s));return t<0.5?api.mix(dark,mid,t*2):api.mix(mid,lite,(t-0.5)*2);});
 cards=cards?cards.merge(m):m;}
// a tapered limb along a polyline: one continuous tube
function limb(pts,r0,r1,seg){addWood(api.tube(pts,r0,seg,function(t){return 1-(1-r1/r0)*t;}));}
function path(p0,dir,len,bend,n){const pts=[p0.slice()];let p=p0.slice();const d=dir.slice();
 for(let i=0;i<n;i++){d[1]+=bend/n;const l=Math.hypot(d[0],d[1],d[2]);p=[p[0]+d[0]/l*len/n,p[1]+d[1]/l*len/n,p[2]+d[2]/l*len/n];pts.push(p.slice());}return pts;}
const sw=function(t){return [0.05*H*api.noise2(t*2.2,3.1)*t,0.05*H*api.noise2(t*2.2,7.7)*t];};
let core=null;
if(v===0){
 // Lombardy poplar: a slim spindle; a straight trunk to near the top, short upswept limbs, cards shingled over the spindle
 const top=H*0.93, tr=H*0.02, Rc=H*(0.07+0.015*rng());
 const tp=[];for(let i=0;i<=6;i++){const t=i/6;const s=sw(t);tp.push([s[0]*0.3,t*top,s[1]*0.3]);}
 limb(tp,tr,tr*0.25,7);
 addWood(api.lathe([[tr*1.9,0],[tr*1.4,0.15],[tr*1.08,0.5],[tr,0.9],[0,0.9]],8));
 const rad=function(t,a){const tip=1-ss(0.55,1.02,t);return Rc*Math.max(0.12,(0.3+0.7*ss(-0.05,0.3,t))*(0.3+0.7*Math.pow(tip,0.4)))*(1+0.2*api.noise2((a||0)*1.3,t*7));};
function ss(a,b,x){let q=(x-a)/(b-a);q=q<0?0:(q>1?1:q);return q*q*(3-2*q);}
 const y0=H*0.1;
 for(let b=0;b<16;b++){const t=0.08+0.8*b/16;const y=y0+(top-y0)*t;const a=b*2.4+rng()*0.5;const L=rad(t,a)*1.1;
  limb(path([0,y,0],[Math.cos(a)*0.45,1,Math.sin(a)*0.45],L*1.6,0.2,2),tr*0.28,tr*0.08,4);}
 // dark inner spindle: what shows through the gaps between cards is shadowed foliage, not sky
 const prof=[];for(let i=0;i<=10;i++){const t=i/10;prof.push([rad(t,0)*0.7,y0+(H-y0)*t]);}prof[10][0]=0;
 core=api.lathe(prof,9).displace(function(x,y,z){return 0.12*Rc*api.noise3(x*1.4,y*0.6,z*1.4);});
 const N=Math.round(190+H*7);
 for(let i=0;i<N;i++){const t=Math.pow(rng(),0.85);const y=y0+(H-y0)*t;const a=rng()*6.283;const rr=rad(t,a)*(0.8+0.28*Math.sqrt(rng()));
  const p=[Math.cos(a)*rr,y,Math.sin(a)*rr];const out=[Math.cos(a)+0.5*(rng()-0.5),0.05+0.35*t+0.5*(rng()-0.5),Math.sin(a)+0.5*(rng()-0.5)];
  const lit=0.7+0.25*Math.cos(a-0.9)+0.25*(t-0.4);
  card(p,out,H*(0.08+0.03*rng()),lit*(0.7+0.3*(rr/Math.max(0.01,rad(t,a)))),true);}
}else{
 // pollarded valley willow: a stout leaning trunk, a knuckle of limbs, a domed crown with long hanging curtains of leaves
 const tt=H*0.4, tr=H*0.042;
 const tp=[];for(let i=0;i<=4;i++){const t=i/4;const s=sw(t);tp.push([s[0],t*tt,s[1]]);}
 limb(tp,tr,tr*0.72,8);
 addWood(api.lathe([[tr*1.45,0],[tr*1.2,0.2],[tr*1.04,0.6],[tr,1.0],[0,1.0]],9));
 addWood(api.sphere(tr*0.95,1).scale(1.1,0.7,1.1).translate(tp[4][0],tt,tp[4][2]));
 const nb=6,Rd=H*(0.34+0.05*rng()),top=H;
 const tips=[];
 for(let b=0;b<nb;b++){const a=b*6.283/nb+rng()*0.5;const ca=Math.cos(a),sa=Math.sin(a);
  const pts=path([tp[4][0]+ca*tr*0.4,tt,tp[4][2]+sa*tr*0.4],[ca*0.6,1.2+0.5*rng(),sa*0.6],Rd*(1.0+0.45*rng()),-0.9,4);limb(pts,tr*0.4,tr*0.12,6);
  const e=pts[pts.length-1];tips.push(e);
  for(let s=0;s<2;s++){const q=pts[2+s];const bb=a+(s?0.6:-0.6);limb(path(q,[Math.cos(bb),0.5,Math.sin(bb)],Rd*0.45,-0.6,2),tr*0.12,tr*0.04,4);}}
 const cy=tt+(top-tt)*0.45;
 // the crown: a lobe of leaves over each limb tip and one over the knuckle, each a dark inner mass shingled with cards
 const lobes=tips.map(function(e){return [e[0]*0.9,e[1]+Rd*0.18,e[2]*0.9,Rd*(0.44+0.14*rng())];});
 lobes.push([0,cy+Rd*0.4,0,Rd*0.62]);
 for(const lb of lobes){const r=lb[3];const cm=api.sphere(r*0.68,1).scale(1,0.85,1).translate(lb[0],lb[1],lb[2]).displace(function(x,y,z){return 0.15*r*api.noise3(x*0.9/r,y*0.9/r,z*0.9/r);});core=core?core.merge(cm):cm;
  const n=Math.round(62+r*15);
  for(let i=0;i<n;i++){const u=rng()*2-1,a=rng()*6.283;const q=Math.sqrt(1-u*u);
   const p=[lb[0]+Math.cos(a)*q*r*(0.8+0.3*rng()),lb[1]+u*r*0.88*(0.85+0.3*rng()),lb[2]+Math.sin(a)*q*r*(0.8+0.3*rng())];
   if(p[1]<tt+0.3)continue;const lit=0.5+0.25*Math.cos(a-0.9)+0.32*u;
   card(p,[Math.cos(a)*q,u*1.3,Math.sin(a)*q],H*(0.085+0.03*rng()),lit*(0.8+0.25*rng()),false);}}
 // curtains: strings of small hanging cards from the underside of each lobe
 for(const lb of lobes){const r=lb[3];const ns0=Math.round(7+r*2.5);
  for(let k=0;k<ns0;k++){const a=rng()*6.283,q=0.45+0.5*Math.sqrt(rng());const x0=lb[0]+Math.cos(a)*r*q,z0=lb[2]+Math.sin(a)*r*q;const y0=lb[1]-r*0.45*(1-q*q*0.6);
   const L=H*(0.12+0.16*rng());const ns=Math.max(2,Math.round(L/(H*0.055)));
   for(let j=0;j<ns;j++){const f=(j+0.5)/ns;const p=[x0+0.05*H*f*Math.cos(a),y0-L*f,z0+0.05*H*f*Math.sin(a)];if(p[1]<0.6)continue;
    card(p,[Math.cos(a),0.1,Math.sin(a)],H*(0.06+0.015*rng()),0.4+0.28*Math.cos(a-0.9)-0.2*f,true);}}}
}
// tiny anchors at the foot keep the trunk on the entity origin whatever the crown's lean
const A=H*0.6;for(const sx of[-1,1])for(const sz of[-1,1])addWood(api.box(0.004,0.004,0.004).translate(sx*A,0.002,sz*A));
api.add(wood,bark);
if(core){core.vertexColor(function(x,y,z){return api.mix(dark,'#0d140a',0.35);});api.add(core,{preset:'leaf',color:'#ffffff',vertexColors:true,roughness:0.95});}
api.add(cards,{foliage:'broadleaf',vertexColors:true,roughness:0.8,metalness:0,doubleSided:true});
const trR=v===0?H*0.02:H*0.05, trH=v===0?H*0.93:H*0.42;
api.collider({kind:'cylinder',halfHeight:trH/2,radius:trR*1.3,offset:[0,trH/2,0]});
return api.build();

himal-tuft.source:
const s=params.size; const nf=Math.min(params.flowers,4); const nb=Math.max(4,Math.min(params.blades,9-nf));
let g=null; const tips=[];
for(let i=0;i<nb;i++){
  const fl=i<nf;
  const h=s*(fl?1.15+api.rng()*0.25:0.55+api.rng()*0.5);
  const bend=fl?0.08+api.rng()*0.1:0.15+api.rng()*0.35;
  const yaw=api.rng()*360;
  const ox=(api.rng()-0.5)*0.16*s, oz=(api.rng()-0.5)*0.16*s;
  const b=api.cone(s*0.035,h,3).translate(0,h/2,0).scale(1,1,0.35).warp((x,y,z)=>[x+bend*h*Math.pow(Math.max(0,y)/h,2),y,z]).rotate(0,yaw,0).translate(ox,0,oz);
  if(g){g.merge(b);}else{g=b;}
  if(fl){const yr=yaw*Math.PI/180; const bx=bend*h; tips.push([ox+bx*Math.cos(yr),h,oz-bx*Math.sin(yr)]);}
}
const tipC=params.color;
g.vertexColor((x,y,z)=>api.mix('#3b5422',tipC,Math.min(1,y/(s*0.9))));
api.add(g,{preset:'leaf',color:'#ffffff',roughness:0.85,vertexColors:true,doubleSided:true});
if(tips.length>0){
  let f=null;
  for(const t of tips){const hm=api.cone(s*0.07,s*0.06,3).rotate(180,0,0).translate(t[0],t[1],t[2]); if(f){f.merge(hm);}else{f=hm;}}
  api.add(f,{color:params.flowerColor,roughness:0.6});
}
return api.build();

himal-village-prop.source:
const v=Math.round(params.variant||0), L=params.length||6, H=params.height||1;
const stone={finish:'stone',color:'#8f877b',roughness:0.93,surface:{layers:[{kind:'lichen',amount:0.4},{kind:'grime',amount:0.4},{kind:'moss',amount:0.3,mask:{up:0.6,noise:0.5}}]}};
const wood={finish:'oak',color:'#6a4a30',roughness:0.85,surface:{layers:[{kind:'edgeWear',amount:0.4},{kind:'grime',amount:0.3}]}};
const clay={finish:'ceramic',color:'#a8603c',roughness:0.8,surface:{layers:[{kind:'grime',amount:0.4}]}};
const soil={finish:'soil',color:'#3e2c1e',roughness:1};
const flower={color:'#e8901c',roughness:0.85};
const leaf={preset:'leaf',color:'#4a6a2c',roughness:0.8};
const cloths=[{finish:'fabric',color:'#8c2f28',roughness:0.95},{finish:'fabric',color:'#2f4f6e',roughness:0.95},{finish:'fabric',color:'#c9a04a',roughness:0.95},{finish:'fabric',color:'#d8d0c0',roughness:0.95}];
if(v===0){ let m=null; const rows=Math.max(2,Math.round(H/0.28)); for(let r=0;r<rows;r++){ let x=-L/2+(r%2)*0.2; const y=r*(H/rows); while(x<L/2-0.15){ const w=0.35+api.rng()*0.3; const ww=Math.min(w,L/2-x); const h=H/rows*(0.85+api.rng()*0.25); const d=0.55-r*0.04; const s=api.box(ww*0.96,h,d*(0.9+api.rng()*0.15)).rotate((api.rng()-0.5)*6,(api.rng()-0.5)*8,(api.rng()-0.5)*5).translate(x+ww/2,y+h/2,(api.rng()-0.5)*0.05); m=m?m.merge(s):s; x+=ww; } } let x=-L/2; while(x<L/2-0.1){ const w=0.3+api.rng()*0.25; const c=api.icosphereRock(0.2,0.4,1).scale(w*1.6,0.7,1.4).translate(x+w/2,H+0.06,0); m.merge(c); x+=w; } api.add(m,stone); api.collider({kind:'box',halfExtents:[L/2,(H+0.15)/2,0.3],offset:[0,(H+0.15)/2,0]}); }
else if(v===1){ const top=2.8*H, lean=0.9*H; let m=api.tube([[-0.22,0,0],[-0.2,top,-lean]],0.045,8); m.merge(api.tube([[0.22,0,0],[0.2,top,-lean]],0.045,8)); const n=Math.floor(top/0.32); for(let i=1;i<n;i++){ const t=i/n; m.merge(api.cylinder(0.025,0.025,0.42,8).rotate(0,0,90).translate(0,t*top,-t*lean)); } m.merge(api.roundedBox(0.6,0.06,0.12,0.02).translate(0,0.03,0.02)); api.add(m,wood); api.collider({kind:'box',halfExtents:[0.28,top/2,0.1],offset:[0,top/2,-lean/2],rotation:[Math.atan2(lean,top)*57.3,0,0]}); }
else if(v===2){ const s=0.55*H; api.add(api.lathe([[0,0],[0.16,0],[0.2,0.05],[0.24,0.25],[0.26,0.36],[0.29,0.38],[0.29,0.42],[0.25,0.42],[0.24,0.4],[0,0.4]],12).scale(s/0.42*0.42/0.42),clay); api.add(api.cylinder(0.24,0.24,0.04,16).scale(s/0.42).translate(0,0.39*s/0.42,0),soil); let f=null, l=null; for(let i=0;i<9;i++){ const a=api.rng()*6.283, r=api.rng()*0.18; const b=api.sphere(0.055+api.rng()*0.03,0).displace((x,y,z)=>0.012*api.noise3(x*60,y*60,z*60)).translate(Math.cos(a)*r,0.5+api.rng()*0.12,Math.sin(a)*r); f=f?f.merge(b):b; const g=api.sphere(0.06,0).scale(1.4,0.4,0.8).rotate(0,a*57,20).translate(Math.cos(a)*(r+0.05),0.44,Math.sin(a)*(r+0.05)); l=l?l.merge(g):g; } api.add(f.scale(s/0.42),flower); api.add(l.scale(s/0.42),leaf); api.collider({kind:'cylinder',halfHeight:0.21*s/0.42,radius:0.28*s/0.42,offset:[0,0.21*s/0.42,0]}); }
else { const ph=2.1*H; let p=api.cylinder(0.05,0.07,ph,10).translate(-L/2,ph/2,0); p.merge(api.cylinder(0.05,0.07,ph,10).translate(L/2,ph/2,0)); p.merge(api.roundedBox(0.5,0.08,0.08,0.02).translate(-L/2,ph-0.1,0)); p.merge(api.roundedBox(0.5,0.08,0.08,0.02).translate(L/2,ph-0.1,0)); api.add(p,wood); const sag=0.25; const pts=[]; for(let i=0;i<=12;i++){ const t=i/12; pts.push([-L/2+t*L,ph-0.1-sag*4*t*(1-t),0]); } api.add(api.tube(pts,0.008,5),{color:'#7a6a55',roughness:0.9}); const n=Math.max(2,Math.floor(L/0.9)); const groups=[null,null,null,null]; for(let i=0;i<n;i++){ const t=(i+0.5)/n; const x=-L/2+t*L, y=ph-0.1-sag*4*t*(1-t); const w=0.45+api.rng()*0.25, h=0.5+api.rng()*0.35; const c=api.roundedBox(w,h,0.02,0.008).displace((a,b,cc)=>0.02*Math.sin(a*9+b*4)).rotate(0,(api.rng()-0.5)*20,0).translate(x,y-h/2,0); const k=i%4; groups[k]=groups[k]?groups[k].merge(c):c; } for(let k=0;k<4;k++) if(groups[k]) api.add(groups[k],cloths[k]); api.collider({kind:'cylinder',halfHeight:ph/2,radius:0.07,offset:[-L/2,ph/2,0]}); api.collider({kind:'cylinder',halfHeight:ph/2,radius:0.07,offset:[L/2,ph/2,0]}); }
return api.build();

himal-yak.source:
const s=params.size||1;const hd=params.headDown||0;const hy=1.12-0.62*hd;const hx=1.28+0.12*hd;
// body from smooth-blended pieces: barrel, high shoulder hump, deep chest, neck, broad head and muzzle, legs
const leg=function(x,z,f){return {shape:'cone',a:[x,0.95,z],b:[x+0.02*f,0.1,z*1.03],ra:0.13,rb:0.075};};
const body={op:'union',k:0.16,items:[
 {shape:'ellipsoid',r:[0.95,0.52,0.48],at:[-0.05,1.18,0]},
 {shape:'ellipsoid',r:[0.5,0.48,0.42],at:[0.48,1.52,0]},
 {shape:'ellipsoid',r:[0.62,0.42,0.44],at:[0.55,1.08,0]},
 {shape:'capsule',a:[0.85,1.4,0],b:[hx-0.12,hy+0.08,0],r:0.25},
 {shape:'ellipsoid',r:[0.3,0.26,0.24],at:[hx,hy,0]},
 {shape:'ellipsoid',r:[0.18,0.15,0.17],at:[hx+0.24,hy-0.14,0]},
 {shape:'ellipsoid',r:[1.02,0.36,0.52],at:[0.02,0.82,0]},
 {shape:'ellipsoid',r:[0.92,0.26,0.56],at:[0.05,0.66,0]},
 leg(0.62,0.22,1),leg(0.62,-0.22,1),leg(-0.68,0.24,-1),leg(-0.68,-0.24,-1)
]};
const m=api.sdf(body,{resolution:23});
// hair: fine tufts everywhere, long combed strands on the skirt below the barrel (stretched noise, pulled down at the hem)
m.displace(function(x,y,z){const sk=y<1.05&&y>0.45&&Math.abs(x)<1.05?1:0;return 0.018*api.noise3(x*9,y*9,z*9)+sk*0.05*api.noise3(x*16,y*2.2,z*16);});
m.warp(function(x,y,z){if(y>0.38&&y<1.0&&Math.abs(x)<1.0){const t=1-(y-0.38)/0.62;const st=0.5+0.5*api.noise3(x*11,0.5,z*11);return [x*(1+0.04*t),y-0.2*t*t*(0.5+0.5*st),z*(1+0.1*t*t)];}return [x,y,z];});
const c=params.color,a=params.accent;
function tint(x,y,z){let t=0.3+0.35*api.noise3(x*2.2,y*2.2,z*2.2);if(y>1.45)t+=0.2;if(x>hx+0.1&&y<hy)t+=0.3;if(y<0.95&&y>0.4)t-=0.25*(0.95-y);return api.mix(c,a,Math.max(0,Math.min(1,t)));}
m.vertexColor(tint);
// tail with a tuft
const tail=api.tube([[-0.98,1.32,0],[-1.12,1.0,0],[-1.14,0.7,0.02]],0.045,5);
const tuft=api.sphere(0.12,0).scale(0.9,1.8,0.9).translate(-1.14,0.58,0.02).displace(function(x,y,z){return 0.03*api.noise3(x*20,y*20,z*20);});
tail.merge(tuft);tail.vertexColor(function(){return c;});
const fur=m.merge(tail);fur.scale(s);
api.add(fur,{preset:'fabric',color:'#ffffff',roughness:0.97});
// horns: pale, curving out, up and forward, darker tips
const hornMat={color:'#ffffff',vertexColors:true,roughness:0.6};
for(const sd of[1,-1]){const hp=[];for(let i=0;i<=8;i++){const t=i/8;const a=t*2.3;hp.push([hx-0.06+0.1*t*t,hy+0.16+0.26*Math.sin(a*0.85)+0.1*t,(0.14+0.34*Math.sin(Math.min(a,1.6)))*sd-0.12*t*t*sd]);}
 const h=api.tube(hp,0.06,8,function(t){return 1-0.85*t;});h.vertexColor(function(x,y,z){return y>hy+0.5?'#3a332b':'#b9a98a';});h.scale(s);api.add(h,hornMat);}
const hoofMat={color:'#1a1512',roughness:0.6};
for(const p of[[0.64,0.225],[0.64,-0.225],[-0.7,0.247],[-0.7,-0.247]]){api.add(api.cylinder(0.075,0.09,0.11,8).translate(p[0],0.055,p[1]).scale(s),hoofMat);}
api.collider({kind:'box',halfExtents:[1.25*s,0.8*s,0.48*s],offset:[0.1*s,0.85*s,0]});
return api.build();

himalaya-river.source:
const W=params.size, D=params.length;
function ss(a,b,x){let t=(x-a)/(b-a); t=Math.min(1,Math.max(0,t)); return t*t*(3-2*t);}
function rx(z){return 25*Math.sin(z*0.011)+12*Math.sin(z*0.029+1);}
function fl(z){return 26*ss(-80,-300,z);}
const path=[];
for(let z=D/2;z>=-D/2;z-=4){path.push([rx(z),fl(z)-0.9,z]);}
const mat={preset:'water',waterKind:'river',waterFlow:[0,1.6],color:'#3fb8b0',roughness:0.08,opacity:0.88};
api.add(api.ribbon(path,21,function(t){return 1+0.1*Math.sin(t*40);}),mat);
const a=api.box(0.02,0.02,0.02).translate(-W/2,-3,-D/2);
a.merge(api.box(0.02,0.02,0.02).translate(W/2,-3,D/2));
api.add(a,mat);
return api.build();

himalaya-valley.source:
const W=params.size, D=params.length, N=params.res;
function ss(a,b,x){let t=(x-a)/(b-a); t=t<0?0:(t>1?1:t); return t*t*(3-2*t);}
function rx(z){return 25*Math.sin(z*0.011)+12*Math.sin(z*0.029+1);}
function fl(z){return 26*ss(-80,-300,z);}
const TS=1.5, FX=-100, FZ=-40, LIP=params.lip, R=params.relief;
function terr(x,z,d){return ss(46,56,d)*(1-ss(118,138,d))*ss(-80,-58,z)*(1-ss(128,150,z))*(1-(1-ss(62,80,Math.abs(z-FZ)))*ss(-45,-60,x));}
function sz(x){return FZ+2.5*Math.sin(x*0.09)+1.5*Math.sin(x*0.23);}
let gDom=0, gEsc=-1e9;
function H(x,z,P){
 gDom=0; gEsc=-1e9;
 const d=Math.abs(x-rx(z));
 const n=api.fbm2(x*0.011,z*0.011,4);
 const n2=api.fbm2(x*0.05+7,z*0.05-3,2);
 const f=fl(z);
 let s=Math.pow(ss(28,240,d),1.25)*R*(1+0.35*n)*(1-0.3*ss(0,60,x-rx(z)));
 const band=ss(90,140,z)*(1-ss(230,280,z));
 const g=22*ss(12,26+4*n2,d)*band;
 const ero=ss(40,200,d)*8*(n2*0.5+0.5)*(0.5+0.5*n);
 let h=f+s+g+ero+2.2*n2*ss(14,40,d);
